**Testing State Transitions**:

```javascript
describe('Order State Machine', () => {
    let orderId;

    beforeEach(async () => {
        const order = await createTestOrder();
        orderId = order.id;
    });

    it('starts with pending status', async () => {
        const response = await request(app)
            .get(`/api/orders/${orderId}`);

        expect(response.body.status).toBe('pending');
    });

    it('transitions from pending to processing', async () => {
        const response = await request(app)
            .post(`/api/orders/${orderId}/process`)
            .set('Authorization', `Bearer ${adminToken}`);

        expect(response.status).toBe(200);
        expect(response.body.status).toBe('processing');
    });

    it('prevents invalid transitions', async () => {
        // Try to ship a pending order (should fail)
        const response = await request(app)
            .post(`/api/orders/${orderId}/ship`)
            .set('Authorization', `Bearer ${adminToken}`);

        expect(response.status).toBe(400);
        expect(response.body.error).toContain('Cannot ship pending order');
    });

    it('allows valid state transitions', async () => {
        // Process order
        await request(app)
            .post(`/api/orders/${orderId}/process`)
            .set('Authorization', `Bearer ${adminToken}`);

        // Now can ship
        const response = await request(app)
            .post(`/api/orders/${orderId}/ship`)
            .set('Authorization', `Bearer ${adminToken}`);

        expect(response.body.status).toBe('shipped');

        // Now can deliver
        const delivered = await request(app)
            .post(`/api/orders/${orderId}/deliver`)
            .set('Authorization', `Bearer ${adminToken}`);

        expect(delivered.body.status).toBe('delivered');
    });

    it('prevents transitioning from terminal states', async () => {
        // Deliver order
        await request(app)
            .post(`/api/orders/${orderId}/process`)
            .set('Authorization', `Bearer ${adminToken}`);
        await request(app)
            .post(`/api/orders/${orderId}/ship`)
            .set('Authorization', `Bearer ${adminToken}`);
        await request(app)
            .post(`/api/orders/${orderId}/deliver`)
            .set('Authorization', `Bearer ${adminToken}`);

        // Try to ship again
        const response = await request(app)
            .post(`/api/orders/${orderId}/ship`)
            .set('Authorization', `Bearer ${adminToken}`);

        expect(response.status).toBe(400);
        expect(response.body.error).toContain('Order already delivered');
    });
});
