**Schema Versioning Tests**:

```javascript
describe('Schema Versioning', () => {
    it('v1 schema is stable', async () => {
        const response = await request(app)
            .get('/api/v1/users/1');

        const v1Schema = {
            type: 'object',
            required: ['id', 'username'], // v1 used 'username' not 'name'
            properties: {
                id: { type: 'integer' },
                username: { type: 'string' }
            }
        };

        const validate = ajv.compile(v1Schema);
        expect(validate(response.body)).toBe(true);
    });

    it('v2 schema evolved', async () => {
        const response = await request(app)
            .get('/api/v2/users/1');

        const v2Schema = {
            type: 'object',
            required: ['id', 'name'], // v2 uses 'name'
            properties: {
                id: { type: 'integer' },
                name: { type: 'string' },
                email: { type: 'string' } // v2 added email
            }
        };

        const validate = ajv.compile(v2Schema);
        expect(validate(response.body)).toBe(true);
    });
});
```

**Schema Validation Best Practices**:

✅ Keep schemas in separate files for reuse
✅ Test that schemas themselves are valid
✅ Version your schemas with your API
✅ Use schemas to generate documentation
✅ Test both required and optional fields
✅ Test edge cases in schemas (min/max values)

```javascript
// schemas/user.js
module.exports = {
    v1: {
        type: 'object',
        required: ['id', 'username'],
        properties: {
            id: { type: 'integer' },
            username: { type: 'string' }
        }
    },
    v2: {
        type: 'object',
        required: ['id', 'name', 'email'],
        properties: {
            id: { type: 'integer' },
            name: { type: 'string' },
            email: { type: 'string', format: 'email' }
        }
    }
};

// test/schemas.test.js - Test schemas themselves
it('user schema v2 is valid JSON Schema', () => {
    const validate = ajv.compile(userSchema.v2);
    expect(validate).toBeDefined();
});
```

**Key Insight**: Schema validation turns implicit expectations into explicit, testable contracts. It's the difference between hoping your API is correct and knowing it is.

Let's build a comprehensive functional test suite for a banking API, incorporating all the concepts we've learned.

**Banking API Endpoints**:

```
POST   /api/accounts           # Create account
GET    /api/accounts           # List accounts
GET    /api/accounts/:id       # Get account details
PUT    /api/accounts/:id       # Update account
DELETE /api/accounts/:id       # Close account

POST   /api/accounts/:id/deposit    # Deposit money
POST   /api/accounts/:id/withdraw   # Withdraw money
POST   /api/accounts/:id/transfer   # Transfer to another account
GET    /api/accounts/:id/transactions # Get transaction history
```

**Test Setup**:

```javascript
// test/banking/setup.js
const request = require('supertest');
const app = require('../../src/app');
const db = require('../../src/db');
const { createTestUser, getAuthToken } = require('../helpers');

// Schema validators
const Ajv = require('ajv');
const addFormats = require('ajv-formats');
const ajv = new Ajv();
addFormats(ajv);

// Load schemas
const accountSchema = require('../schemas/account.schema');
const transactionSchema = require('../schemas/transaction.schema');
const errorSchema = require('../schemas/error.schema');

// Compile validators
const validateAccount = ajv.compile(accountSchema);
const validateTransaction = ajv.compile(transactionSchema);
const validateError = ajv.compile(errorSchema);

beforeAll(async () => {
    await db.migrate.latest();
});

afterAll(async () => {
    await db.migrate.rollback();
    await db.destroy();
});

beforeEach(async () => {
    await db.beginTransaction();
});

afterEach(async () => {
    await db.rollbackTransaction();
});

// Helper functions
async function createAccount(userId, overrides = {}) {
    const accountData = {
        type: 'checking',
        currency: 'USD',
        initialDeposit: 100,
        ...overrides
    };

    const response = await request(app)
        .post('/api/accounts')
        .set('Authorization', `Bearer ${await getAuthToken(userId)}`)
        .send(accountData);

    return response.body;
}
```

**Account Creation Tests**:

```javascript
// test/banking/accounts.create.test.js
describe('POST /api/accounts - Create Account', () => {
    let user, token;

    beforeEach(async () => {
        user = await createTestUser();
        token = await getAuthToken(user);
    });

    describe('Validation Tests', () => {
        it('returns 400 when account type is invalid', async () => {
            const response = await request(app)
                .post('/api/accounts')
                .set('Authorization', `Bearer ${token}`)
                .send({
                    type: 'invalid-type',
                    currency: 'USD'
                });

            expect(response.status).toBe(400);
            expect(validateError(response.body)).toBe(true);
            expect(response.body.error.details.type).toBeDefined();
        });

        it('returns 400 when currency is invalid', async () => {
            const response = await request(app)
                .post('/api/accounts')
                .set('Authorization', `Bearer ${token}`)
                .send({
                    type: 'checking',
                    currency: 'INVALID'
                });

            expect(response.status).toBe(400);
            expect(response.body.error.details.currency).toBeDefined();
        });

        it('returns 400 when initial deposit is negative', async () => {
            const response = await request(app)
                .post('/api/accounts')
                .set('Authorization', `Bearer ${token}`)
                .send({
                    type: 'checking',
                    currency: 'USD',
                    initialDeposit: -100
                });

            expect(response.status).toBe(400);
            expect(response.body.error.details.initialDeposit).toBeDefined();
        });

        it('returns 400 when initial deposit exceeds maximum', async () => {
            const response = await request(app)
                .post('/api/accounts')
                .set('Authorization', `Bearer ${token}`)
                .send({
                    type: 'checking',
                    currency: 'USD',
                    initialDeposit: 1000000 // Max 500,000
                });

            expect(response.status).toBe(400);
            expect(response.body.error.details.initialDeposit).toContain('maximum');
        });

        it('returns 401 when not authenticated', async () => {
            const response = await request(app)
                .post('/api/accounts')
                .send({
                    type: 'checking',
                    currency: 'USD'
                });

            expect(response.status).toBe(401);
            expect(response.headers['www-authenticate']).toBeDefined();
        });
    });

    describe('Success Cases', () => {
        it('creates checking account successfully', async () => {
            const response = await request(app)
                .post('/api/accounts')
                .set('Authorization', `Bearer ${token}`)
                .send({
                    type: 'checking',
                    currency: 'USD',
                    initialDeposit: 500
                });

            // Status code
            expect(response.status).toBe(201);

            // Headers
            expect(response.headers['content-type']).toContain('application/json');
            expect(response.headers.location).toBeDefined();

            // Schema validation
            expect(validateAccount(response.body)).toBe(true);

            // Specific field validation
            const account = response.body;
            expect(account.type).toBe('checking');
            expect(account.currency).toBe('USD');
            expect(account.balance).toBe(500);
            expect(account.status).toBe('active');
            expect(account.userId).toBe(user.id);

            // Date format
            expect(account.createdAt).toMatch(/^\d{4}-\d{2}-\d{2}T/);
        });

        it('creates savings account with zero initial deposit', async () => {
            const response = await request(app)
                .post('/api/accounts')
                .set('Authorization', `Bearer ${token}`)
                .send({
                    type: 'savings',
                    currency: 'EUR',
                    initialDeposit: 0
                });

            expect(response.status).toBe(201);
            expect(response.body.type).toBe('savings');
            expect(response.body.currency).toBe('EUR');
            expect(response.body.balance).toBe(0);
        });

        it('returns account in GET after creation', async () => {
            const createResponse = await request(app)
                .post('/api/accounts')
                .set('Authorization', `Bearer ${token}`)
                .send({
                    type: 'checking',
                    currency: 'USD'
                });

            const accountId = createResponse.body.id;

            const getResponse = await request(app)
                .get(`/api/accounts/${accountId}`)
                .set('Authorization', `Bearer ${token}`);

            expect(getResponse.status).toBe(200);
            expect(getResponse.body.id).toBe(accountId);
            expect(getResponse.body.balance).toBe(0);
        });
    });

    describe('Business Rules', () => {
        it('prevents creating more than 5 accounts', async () => {
            // Create 5 accounts
            for (let i = 0; i < 5; i++) {
                await request(app)
                    .post('/api/accounts')
                    .set('Authorization', `Bearer ${token}`)
                    .send({ type: 'checking', currency: 'USD' });
            }

            // Try to create 6th
            const response = await request(app)
                .post('/api/accounts')
                .set('Authorization', `Bearer ${token}`)
                .send({ type: 'checking', currency: 'USD' });

            expect(response.status).toBe(400);
            expect(response.body.error.message).toContain('Maximum 5 accounts');
        });

        it('enforces minimum age for account holders', async () => {
            const minorUser = await createTestUser({ age: 17 });
            const minorToken = await getAuthToken(minorUser);

            const response = await request(app)
                .post('/api/accounts')
                .set('Authorization', `Bearer ${minorToken}`)
                .send({ type: 'checking', currency: 'USD' });

            expect(response.status).toBe(400);
            expect(response.body.error.message).toContain('Must be 18 or older');
        });
    });
});
