```javascript
// test/banking/transactions.test.js
describe('Account Transactions', () => {
    let user, token, account;

    beforeEach(async () => {
        user = await createTestUser();
        token = await getAuthToken(user);
        account = await createAccount(user.id, { initialDeposit: 1000 });
    });

    describe('POST /api/accounts/:id/deposit', () => {
        it('deposits money successfully', async () => {
            const response = await request(app)
                .post(`/api/accounts/${account.id}/deposit`)
                .set('Authorization', `Bearer ${token}`)
                .send({ amount: 500 });

            // Status and headers
            expect(response.status).toBe(200);

            // Schema validation
            expect(validateTransaction(response.body)).toBe(true);

            // Business logic
            expect(response.body.type).toBe('deposit');
            expect(response.body.amount).toBe(500);
            expect(response.body.balance).toBe(1500); // 1000 + 500

            // Verify account updated
            const accountCheck = await request(app)
                .get(`/api/accounts/${account.id}`)
                .set('Authorization', `Bearer ${token}`);
            expect(accountCheck.body.balance).toBe(1500);
        });

        it('validates deposit amount', async () => {
            const response = await request(app)
                .post(`/api/accounts/${account.id}/deposit`)
                .set('Authorization', `Bearer ${token}`)
                .send({ amount: -100 });

            expect(response.status).toBe(400);
            expect(response.body.error.details.amount).toBeDefined();
        });

        it('enforces maximum deposit limit', async () => {
            const response = await request(app)
                .post(`/api/accounts/${account.id}/deposit`)
                .set('Authorization', `Bearer ${token}`)
                .send({ amount: 50000 }); // Max 10,000 per day

            expect(response.status).toBe(400);
            expect(response.body.error.message).toContain('Daily deposit limit');
        });
    });

    describe('POST /api/accounts/:id/withdraw', () => {
        it('withdraws money successfully', async () => {
            const response = await request(app)
                .post(`/api/accounts/${account.id}/withdraw`)
                .set('Authorization', `Bearer ${token}`)
                .send({ amount: 300 });

            expect(response.status).toBe(200);
            expect(response.body.type).toBe('withdrawal');
            expect(response.body.amount).toBe(300);
            expect(response.body.balance).toBe(700); // 1000 - 300
        });

        it('prevents overdraft', async () => {
            const response = await request(app)
                .post(`/api/accounts/${account.id}/withdraw`)
                .set('Authorization', `Bearer ${token}`)
                .send({ amount: 2000 }); // More than balance

            expect(response.status).toBe(400);
            expect(response.body.error.message).toContain('Insufficient funds');
        });

        it('prevents withdrawing from frozen account', async () => {
            // Freeze account
            await request(app)
                .put(`/api/accounts/${account.id}`)
                .set('Authorization', `Bearer ${await getAuthToken(adminUser)}`)
                .send({ status: 'frozen' });

            const response = await request(app)
                .post(`/api/accounts/${account.id}/withdraw`)
                .set('Authorization', `Bearer ${token}`)
                .send({ amount: 100 });

            expect(response.status).toBe(400);
            expect(response.body.error.message).toContain('Account is frozen');
        });
    });

    describe('POST /api/accounts/:id/transfer', () => {
        let recipientAccount;

        beforeEach(async () => {
            const recipient = await createTestUser();
            recipientAccount = await createAccount(recipient.id, { initialDeposit: 500 });
        });

        it('transfers money between accounts', async () => {
            const response = await request(app)
                .post(`/api/accounts/${account.id}/transfer`)
                .set('Authorization', `Bearer ${token}`)
                .send({
                    toAccountId: recipientAccount.id,
                    amount: 200,
                    description: 'Test transfer'
                });

            expect(response.status).toBe(200);
            expect(response.body.type).toBe('transfer_out');
            expect(response.body.amount).toBe(200);
            expect(response.body.balance).toBe(800); // 1000 - 200

            // Check recipient account
            const recipientCheck = await request(app)
                .get(`/api/accounts/${recipientAccount.id}`)
                .set('Authorization', `Bearer ${await getAuthToken(recipientAccount.userId)}`);
            expect(recipientCheck.body.balance).toBe(700); // 500 + 200

            // Check transaction history for both accounts
            const senderHistory = await request(app)
                .get(`/api/accounts/${account.id}/transactions`)
                .set('Authorization', `Bearer ${token}`);
            expect(senderHistory.body.data[0].type).toBe('transfer_out');

            const recipientHistory = await request(app)
                .get(`/api/accounts/${recipientAccount.id}/transactions`)
                .set('Authorization', `Bearer ${await getAuthToken(recipientAccount.userId)}`);
            expect(recipientHistory.body.data[0].type).toBe('transfer_in');
        });

        it('prevents transfer to non-existent account', async () => {
            const response = await request(app)
                .post(`/api/accounts/${account.id}/transfer`)
                .set('Authorization', `Bearer ${token}`)
                .send({
                    toAccountId: 999999,
                    amount: 100
                });

            expect(response.status).toBe(404);
        });

        it('prevents transfer to same account', async () => {
            const response = await request(app)
                .post(`/api/accounts/${account.id}/transfer`)
                .set('Authorization', `Bearer ${token}`)
                .send({
                    toAccountId: account.id,
                    amount: 100
                });

            expect(response.status).toBe(400);
            expect(response.body.error.message).toContain('Cannot transfer to same account');
        });

        it('ensures atomicity (both accounts update or none)', async () => {
            // This transfer will fail due to insufficient funds
            const response = await request(app)
                .post(`/api/accounts/${account.id}/transfer`)
                .set('Authorization', `Bearer ${token}`)
                .send({
                    toAccountId: recipientAccount.id,
                    amount: 2000 // More than balance
                });

            expect(response.status).toBe(400);

            // Verify neither account balance changed
            const senderCheck = await request(app)
