**Error Response Testing Checklist**:

| Aspect | What to Test | Example Assertion |
|--------|--------------|-------------------|
| **Status Code** | Correct for error type | `expect(response.status).toBe(404)` |
| **Error Structure** | Consistent format | `expect(validateError(response.body)).toBe(true)` |
| **Error Message** | Clear and helpful | `expect(error.message).toContain('not found')` |
| **Error Details** | Field-specific | `expect(error.details.email).toBeDefined()` |
| **Error Code** | App-specific codes | `expect(error.code).toBe('RESOURCE_NOT_FOUND')` |
| **Timestamp** | When error occurred | `expect(new Date(error.timestamp)).toBeInstanceOf(Date)` |
| **Correlation ID** | For debugging | `expect(error.correlationId).toBeDefined()` |
| **Headers** | Proper headers | `expect(response.headers['retry-after']).toBeDefined()` |
| **No Leaks** | No stack traces | `expect(errorBody).not.toContain('stack')` |
| **Performance** | Fast responses | `expect(duration).toBeLessThan(500)` |

**Key Insight**: Error responses are part of your API contract. Test them with the same rigor as success responses. Consistent, helpful errors make debugging easier for API consumers and improve the overall developer experience.

Let's build a complete negative test suite for a payment processing API, incorporating all types of negative testing.

**Payment API Endpoints**:

```
POST   /api/payments/process    # Process payment
POST   /api/payments/refund     # Refund payment
GET    /api/payments/:id        # Get payment details
POST   /api/customers           # Create customer
GET    /api/customers/:id       # Get customer
```

**Complete Test Setup**:

```javascript
// test/payments/negative/setup.js
const request = require('supertest');
const app = require('../../../src/app');
const db = require('../../../src/db');
const { createTestUser, getAuthToken } = require('../../helpers');
const Ajv = require('ajv');
const addFormats = require('ajv-formats');

const ajv = new Ajv();
addFormats(ajv);

// Error response schema
const errorSchema = {
    type: 'object',
    required: ['error'],
    properties: {
        error: {
            type: 'object',
            required: ['code', 'message'],
            properties: {
                code: { type: 'integer' },
                message: { type: 'string' },
                details: { type: 'object' },
                timestamp: { type: 'string', format: 'date-time' },
                path: { type: 'string' },
                correlationId: { type: 'string' }
            }
        }
    }
};

const validateError = ajv.compile(errorSchema);

// Helper to test error responses
async function assertErrorResponse(response, expectedStatus) {
    expect(response.status).toBe(expectedStatus);
    expect(validateError(response.body)).toBe(true);

    const error = response.body.error;
    expect(error.code).toBe(expectedStatus);
    expect(error.message.length).toBeGreaterThan(0);

    return error;
}

module.exports = {
    request,
    app,
    db,
    createTestUser,
    getAuthToken,
    assertErrorResponse
};
