            .set('Idempotency-Key', idempotencyKey)
            .send({
                items: [{ productId: 1, quantity: 1 }],
                paymentMethod: 'card'
            });

        // Should return same order, not create duplicate
        expect(secondResponse.status).toBe(200); // or 409
        expect(secondResponse.body.id).toBe(orderId);

        // Verify only one order in database
        const ordersResponse = await request(app)
            .get('/api/orders')
            .set('Authorization', `Bearer ${authToken}`);

        const matchingOrders = ordersResponse.body.data.filter(o => o.id === orderId);
        expect(matchingOrders.length).toBe(1);
