        // Should fail quickly without calling payment service
        expect([503, 500]).toContain(response.status);
        expect(duration).toBeLessThan(100); // Fast failure
        expect(response.body.error.message).toMatch(/circuit|unavailable/i);

        // Verify payment service was not called for this request
        expect(paymentServiceMock.isDone()).toBe(false);
    });

    it('closes circuit after recovery period', async () => {
        const authToken = await getAuthToken();

        // This test requires manipulating time or waiting
        // Often done with test configurations that shorten recovery periods

        // 1. Cause circuit to open (multiple failures)
        for (let i = 0; i < 5; i++) {
            paymentServiceMock
                .post('/api/payments/process')
                .reply(500, {});

            await request(app)
                .post('/api/checkout')
                .set('Authorization', `Bearer ${authToken}`)
                .send({ amount: 100 });
        }

        // 2. Wait for recovery period (or use test config with short period)
        await new Promise(resolve => setTimeout(resolve, 5000));

        // 3. Next request should attempt to call service again
        paymentServiceMock
            .post('/api/payments/process')
            .reply(200, { status: 'success' });

        const response = await request(app)
            .post('/api/checkout')
            .set('Authorization', `Bearer ${authToken}`)
            .send({ amount: 100 });

        expect(response.status).toBe(200);
        expect(paymentServiceMock.isDone()).toBe(true); // Service was called
    });
});
