**Testing Transactions and Rollbacks**:

```javascript
describe('Transaction Integration', () => {
    let db;

    beforeAll(() => {
        db = getTestDatabase();
    });

    it('commits transaction when all operations succeed', async () => {
        // Start transaction
        await db.query('BEGIN');

        try {
            // Insert order
            const orderResult = await db.query(
                'INSERT INTO orders (user_id, total, status, created_at) VALUES ($1, $2, $3, $4) RETURNING id',
                [1, 100.00, 'pending', new Date()]
            );
            const orderId = orderResult.rows[0].id;

            // Insert order items
            await db.query(
                'INSERT INTO order_items (order_id, product_id, quantity, price) VALUES ($1, $2, $3, $4)',
                [orderId, 123, 2, 50.00]
            );

            // Update inventory
            await db.query(
                'UPDATE products SET stock = stock - $1 WHERE id = $2',
                [2, 123]
            );

            // Commit transaction
            await db.query('COMMIT');

            // Verify all changes persisted
            const order = await db.query('SELECT * FROM orders WHERE id = $1', [orderId]);
            expect(order.rows.length).toBe(1);

            const items = await db.query('SELECT * FROM order_items WHERE order_id = $1', [orderId]);
            expect(items.rows.length).toBe(1);

            const product = await db.query('SELECT stock FROM products WHERE id = $1', [123]);
            expect(product.rows[0].stock).toBeLessThan(10); // Original - 2

        } catch (error) {
            await db.query('ROLLBACK');
            throw error;
        }
    });

    it('rolls back transaction when any operation fails', async () => {
        // Get original stock
        const originalStock = await db.query('SELECT stock FROM products WHERE id = $1', [123]);
        const originalValue = originalStock.rows[0].stock;

        // Start transaction
        await db.query('BEGIN');

        try {
            // Insert order (will succeed)
            const orderResult = await db.query(
                'INSERT INTO orders (user_id, total, status, created_at) VALUES ($1, $2, $3, $4) RETURNING id',
                [1, 100.00, 'pending', new Date()]
            );
            const orderId = orderResult.rows[0].id;

            // Update inventory (will succeed)
            await db.query(
                'UPDATE products SET stock = stock - $1 WHERE id = $2',
                [2, 123]
            );

            // This operation will fail (invalid product)
            await db.query(
                'INSERT INTO order_items (order_id, product_id, quantity, price) VALUES ($1, $2, $3, $4)',
                [orderId, 999999, 2, 50.00] // Non-existent product
            );

            await db.query('COMMIT');

            // Should not reach here
            expect(true).toBe(false);
        } catch (error) {
            await db.query('ROLLBACK');

            // Verify order was rolled back
            const order = await db.query('SELECT * FROM orders WHERE id = $1', [orderResult.rows[0].id]);
            expect(order.rows.length).toBe(0);

            // Verify inventory was rolled back
            const newStock = await db.query('SELECT stock FROM products WHERE id = $1', [123]);
            expect(newStock.rows[0].stock).toBe(originalValue); // Back to original
        }
    });
});
