**Testing Retry and Dead Letter Queues**:

```javascript
describe('Retry and Dead Letter Handling', () => {
    let queue, failingService;

    beforeEach(() => {
        queue = app.get('messageQueue');
        failingService = app.get('failingService');
        queue.clear();

        jest.spyOn(failingService, 'process');
    });

    it('retries failed messages', async () => {
        // Make service fail first two times, succeed on third
        failingService.process
            .mockRejectedValueOnce(new Error('Temporary failure'))
            .mockRejectedValueOnce(new Error('Temporary failure'))
            .mockResolvedValueOnce({ success: true });

        // Publish message
        await queue.publish('task.process', { taskId: 123 });

        // Wait for processing and retries
        await new Promise(resolve => setTimeout(resolve, 3000));

        // Verify service was called 3 times (initial + 2 retries)
        expect(failingService.process).toHaveBeenCalledTimes(3);

        // Verify message was processed successfully
        const result = await queue.waitForMessage('task.completed', msg => 
            msg.taskId === 123
        );

        expect(result).toBeDefined();
    });

    it('moves permanently failed messages to dead letter queue', async () => {
        // Make service always fail
        failingService.process.mockRejectedValue(new Error('Permanent failure'));

        // Publish message
        await queue.publish('task.process', { taskId: 456 });

        // Wait for all retries to exhaust
        await new Promise(resolve => setTimeout(resolve, 5000));

        // Verify message ended up in DLQ
        const dlqMessage = await queue.waitForMessage('task.process.dlq', msg => 
            msg.originalMessage.taskId === 456
        );

        expect(dlqMessage).toBeDefined();
        expect(dlqMessage.error).toContain('Permanent failure');
        expect(dlqMessage.retryCount).toBe(3); // Assuming 3 retries
    });
});
