        // First request
        await request(app)
            .get('/api/currency/convert?from=USD&to=EUR&amount=100')
            .set('Authorization', `Bearer ${authToken}`);

        // Advance time past TTL (e.g., 1 hour)
        jest.advanceTimersByTime(61 * 60 * 1000);

        // Second request should hit API again
        const response = await request(app)
            .get('/api/currency/convert?from=USD&to=EUR&amount=100')
            .set('Authorization', `Bearer ${authToken}`);

        expect(exchangeRateMock.isDone()).toBe(true);

        jest.useRealTimers();
    });
});
