End-to-end integration tests verify complete business workflows across all services, databases, and external dependencies.

**E2E Integration Test Characteristics**:

| Aspect | Description |
|--------|-------------|
| **Scope** | Multiple services, databases, queues |
| **Environment** | Staging or isolated test environment |
| **Data** | Realistic test data, fixtures |
| **Coverage** | Critical business workflows only |
| **Frequency** | Pre-release, nightly, not per-commit |
| **Duration** | Minutes to hours |

**Complete E2E Test Setup**:

```javascript
// test/e2e/setup.js
const { spawn } = require('child_process');
const waitOn = require('wait-on');

class E2ETestEnvironment {
    async setup() {
        console.log('Setting up E2E test environment...');

        // Start all services using docker-compose
        this.compose = spawn('docker-compose', ['up', '-d'], {
            cwd: path.join(__dirname, '../../docker')
        });

        // Wait for services to be ready
        await waitOn({
            resources: [
                'tcp:localhost:3000', // API Gateway
                'tcp:localhost:5432', // PostgreSQL
                'tcp:localhost:6379', // Redis
                'tcp:localhost:9092', // Kafka
            ],
            timeout: 60000
        });

        // Run database migrations
        await runMigrations();

        // Load test data
        await loadFixtures();

        console.log('E2E environment ready');
    }

    async teardown() {
        console.log('Tearing down E2E environment...');

        // Stop all services
        spawn('docker-compose', ['down', '-v'], {
            cwd: path.join(__dirname, '../../docker')
        });
    }
}

// Global setup
beforeAll(async () => {
    await global.e2eEnv.setup();
});

afterAll(async () => {
    await global.e2eEnv.teardown();
});
