**Key Insight**: Smart test selection can reduce regression test time by 70-90% while still catching 95% of regressions. The key is finding the right balance.

Impact analysis helps you understand what might break when you make changes. It's the foundation of effective regression testing.

**Levels of Impact Analysis**:

| Level | What It Analyzes | Tools |
|-------|------------------|-------|
| **Code** | File dependencies, call graphs | Static analysis, AST |
| **API Contract** | Endpoint changes, schema changes | OpenAPI diff |
| **Data** | Database schema, migrations | Schema comparison |
| **Runtime** | Service dependencies, traffic patterns | Tracing, metrics |
| **Business** | Feature usage, user impact | Analytics, monitoring |

**API Contract Impact Analysis**:

```javascript
// test/regression/contract-impact.js
const OpenAPIDiff = require('openapi-diff');
const fs = require('fs');

class ContractImpactAnalyzer {
    constructor(oldSpecPath, newSpecPath) {
        this.oldSpec = JSON.parse(fs.readFileSync(oldSpecPath, 'utf8'));
        this.newSpec = JSON.parse(fs.readFileSync(newSpecPath, 'utf8'));
    }

    async analyze() {
        const diff = await OpenAPIDiff.diff(this.oldSpec, this.newSpec);

        return {
            breakingChanges: this.findBreakingChanges(diff),
            nonBreakingChanges: this.findNonBreakingChanges(diff),
            unmodified: this.findUnmodifiedEndpoints(diff),
            impact: this.assessImpact(diff)
        };
    }

    findBreakingChanges(diff) {
        const breaking = [];

        // Check for removed endpoints
        if (diff.paths?.removed) {
            breaking.push(...diff.paths.removed.map(p => ({
                type: 'endpoint_removed',
                path: p,
                impact: 'high'
            })));
        }

        // Check for changed request/response schemas
        if (diff.components?.schemas?.changed) {
            for (const [schema, changes] of Object.entries(diff.components.schemas.changed)) {
                if (this.isBreakingSchemaChange(changes)) {
                    breaking.push({
                        type: 'schema_breaking',
                        schema,
                        changes,
                        impact: 'high'
                    });
                }
            }
        }

        return breaking;
    }

    isBreakingSchemaChange(changes) {
        // Check for:
        // - Required field removed
        // - Field type changed
        // - Enum values removed
        // - Format changed
        return changes.required?.removed?.length > 0 ||
               changes.properties?.removed?.length > 0 ||
               changes.properties?.changed?.some(c => c.type?.changed);
    }

    assessImpact(diff) {
        const impact = {
            critical: [],  // Must test all clients
            high: [],      // Test affected endpoints thoroughly
            medium: [],    // Test affected endpoints
            low: []        // Minimal testing needed
        };

        // Categorize changes by impact level
        for (const change of diff.breakingChanges || []) {
            impact.critical.push(change);
        }

        // Non-breaking but significant changes
        for (const change of diff.nonBreakingChanges || []) {
            if (this.isSignificantChange(change)) {
                impact.high.push(change);
            } else {
                impact.medium.push(change);
            }
        }

        return impact;
    }
}
```

**Database Schema Impact Analysis**:

```javascript
// test/regression/database-impact.js
class DatabaseImpactAnalyzer {
    constructor(oldSchema, newSchema) {
        this.oldSchema = oldSchema;
        this.newSchema = newSchema;
    }

    analyze() {
        const impact = {
            breaking: [],
            safe: [],
            rollback: []
        };

        // Check table changes
        for (const [table, newTableSchema] of Object.entries(this.newSchema.tables)) {
            const oldTableSchema = this.oldSchema.tables[table];

            if (!oldTableSchema) {
                // New table - safe
                impact.safe.push({ type: 'new_table', table });
                continue;
            }

            // Check column changes
            for (const [column, newColumnDef] of Object.entries(newTableSchema.columns)) {
                const oldColumnDef = oldTableSchema.columns[column];

                if (!oldColumnDef) {
                    // New column - safe if nullable or has default
                    if (newColumnDef.nullable || newColumnDef.default !== undefined) {
                        impact.safe.push({ type: 'new_column', table, column });
                    } else {
                        impact.breaking.push({ 
                            type: 'new_required_column', 
                            table, 
                            column,
                            reason: 'NOT NULL without default'
                        });
                    }
                } else if (this.isBreakingColumnChange(oldColumnDef, newColumnDef)) {
                    impact.breaking.push({
                        type: 'column_change',
                        table,
                        column,
                        oldType: oldColumnDef.type,
                        newType: newColumnDef.type,
                        reason: 'Type change may break queries'
                    });
                }
            }

            // Check removed columns
            for (const column of Object.keys(oldTableSchema.columns)) {
                if (!newTableSchema.columns[column]) {
                    impact.breaking.push({
                        type: 'column_removed',
                        table,
                        column,
                        reason: 'Queries referencing this column will fail'
                    });
                }
            }
        }

        return impact;
    }

    isBreakingColumnChange(oldCol, newCol) {
        // Type changes are usually breaking
        if (oldCol.type !== newCol.type) return true;

        // Making a column NOT NULL without default is breaking
        if (!oldCol.nullable && newCol.nullable) return false; // Making nullable is safe
        if (oldCol.nullable && !newCol.nullable && newCol.default === undefined) {
            return true;
        }

        return false;
    }
}
