// Generate impact report for PR
class ImpactReport {
    constructor(changes, impact) {
        this.changes = changes;
        this.impact = impact;
    }

    generateMarkdown() {
        let markdown = '# Impact Analysis Report\n\n';

        markdown += '## Changes Detected\n\n';
        for (const change of this.changes) {
            markdown += `- **${change.type}**: ${change.description}\n`;
        }

        markdown += '\n## Breaking Changes\n\n';
        if (this.impact.breaking.length === 0) {
            markdown += '✅ No breaking changes detected\n';
        } else {
            for (const breaking of this.impact.breaking) {
                markdown += `❌ ${breaking.type}: ${breaking.reason}\n`;
            }
        }

        markdown += '\n## Recommended Test Strategy\n\n';
        markdown += '| Risk Level | Tests to Run |\n';
        markdown += '|------------|--------------|\n';

        for (const [risk, endpoints] of Object.entries(this.impact.testStrategy)) {
            markdown += `| **${risk}** | ${endpoints.join(', ') || 'None'} |\n`;
        }

        return markdown;
    }
}
