**Charter-Based Session in Practice**:

```javascript
// exploratory-session.js
class ExploratorySession {
    constructor(charter) {
        this.charter = charter;
        this.startTime = null;
        this.observations = [];
        this.issues = [];
        this.questions = [];
        this.api = null; // Would be initialized with API client
    }

    start() {
        this.startTime = new Date();
        console.log(`🚀 Starting session: ${this.charter.title}`);
        console.log(`Mission: ${this.charter.mission}`);
        console.log(`Timebox: ${this.charter.timebox} minutes`);

        return this;
    }

    async explore() {
        if (!this.startTime) {
            throw new Error('Session not started. Call start() first.');
        }

        const endTime = new Date(this.startTime.getTime() + this.charter.timebox * 60000);

        while (new Date() < endTime) {
            const test = this.designNextTest();
            const result = await this.executeTest(test);
            this.analyze(result);

            // Check if we've exceeded timebox after each test
            if (new Date() >= endTime) {
                console.log('⏰ Timebox reached');
                break;
            }
        }
    }

    designNextTest() {
        // Based on previous observations, design next test
        const lastObservation = this.observations[this.observations.length - 1];

        if (lastObservation?.unexpected) {
            // Explore unexpected behavior deeper
            return this.createFollowUpTest(lastObservation);
        }

        // Try next area from charter
        const nextArea = this.getNextAreaFromCharter();
        if (nextArea) {
            return {
                type: 'charter-area',
                area: nextArea,
                description: `Exploring ${nextArea} from charter`
            };
        }

        // If no more areas, try variations of previous tests
        return this.createVariationTest();
    }

    createFollowUpTest(observation) {
        // Create a test that digs deeper into unexpected behavior
        return {
            type: 'follow-up',
            basedOn: observation,
            description: `Follow-up on: ${observation.test.description}`,
            variation: this.generateVariation(observation.test)
        };
    }

    generateVariation(test) {
        // Generate a variation of a previous test
        // For example, if test used value 5, try 6, 4, -5, etc.
        const variations = {
            number: (val) => [val + 1, val - 1, -val, val * 2],
            string: (val) => [val + 'a', val.slice(1), val.toUpperCase(), ''],
            boolean: (val) => [!val]
        };

        const type = typeof test.value;
        if (variations[type]) {
            const possible = variations[type](test.value);
            return possible[Math.floor(Math.random() * possible.length)];
        }

        return null;
    }

    getNextAreaFromCharter() {
        // Get the next unexplored area from the charter
        const exploredAreas = this.observations.map(o => o.area);
        const charterAreas = this.charter.areas || [];

        return charterAreas.find(area => !exploredAreas.includes(area));
    }

    createVariationTest() {
        // Create a variation of a random previous test
        if (this.observations.length === 0) {
            return {
                type: 'initial',
                description: 'Starting exploration'
            };
        }

        const randomIndex = Math.floor(Math.random() * this.observations.length);
        const previous = this.observations[randomIndex];

        return {
            type: 'variation',
            basedOn: previous,
            description: `Variation of: ${previous.test.description}`,
            variation: this.generateVariation(previous.test)
        };
    }

    async executeTest(test) {
        // Simulate executing a test
        console.log(`🧪 Executing: ${test.description}`);

        // This would be replaced with actual API call
        await new Promise(resolve => setTimeout(resolve, 500));

        // Simulate response (in real scenario, this would be from API)
        const response = {
            status: Math.random() > 0.7 ? 400 : 200,
            body: { success: true },
            time: Math.floor(Math.random() * 200)
        };

        return {
            test,
            response,
            expected: 200,
            actual: response.status,
            timestamp: new Date().toISOString()
        };
    }

    analyze(result) {
        const observation = {
            timestamp: result.timestamp,
            test: result.test,
            response: result.response,
            expected: result.expected,
            actual: result.actual,
            area: result.test.area,
            unexpected: result.expected !== result.actual
        };

        this.observations.push(observation);

        if (observation.unexpected) {
            const severity = this.assessSeverity(result);

            this.issues.push({
                description: `Unexpected response for ${result.test.description}`,
                severity: severity,
                details: observation,
                timestamp: new Date().toISOString()
            });

            this.questions.push(`What happens if we modify ${JSON.stringify(result.test)} further?`);

            console.log(`🐛 Found issue: ${severity} - ${observation.description}`);
        }
    }

    assessSeverity(result) {
        // Determine severity based on response
        if (result.response?.status >= 500) {
            return 'critical';
        }
        if (result.response?.status >= 400) {
            return 'medium';
        }
        if (result.expected !== result.actual) {
            return 'low';
        }
        return 'info';
    }

    summarize() {
        if (!this.startTime) {
            return { error: 'Session not started' };
        }

        const duration = (new Date() - this.startTime) / 60000;

        // Group issues by severity
        const issuesBySeverity = this.issues.reduce((acc, issue) => {
            acc[issue.severity] = (acc[issue.severity] || 0) + 1;
            return acc;
        }, {});

        return {
            charter: this.charter.title,
            duration: `${duration.toFixed(1)} minutes`,
            observations: this.observations.length,
            issues: this.issues.length,
            issuesBySeverity,
            criticalIssues: this.issues.filter(i => i.severity === 'critical').length,
            questions: this.questions,
            findings: this.issues.map(i => ({
                description: i.description,
                severity: i.severity
            })),
            coverage: this.calculateCoverage(),
            timestamp: new Date().toISOString()
        };
    }

    calculateCoverage() {
        // Calculate what percentage of charter areas were explored
        if (!this.charter.areas || this.charter.areas.length === 0) {
            return 'N/A';
        }

        const exploredAreas = new Set(this.observations.map(o => o.area).filter(Boolean));
        return `${(exploredAreas.size / this.charter.areas.length * 100).toFixed(0)}%`;
    }

    generateReport() {
        const summary = this.summarize();

        return {
            session: summary,
            charter: this.charter,
            timeline: this.observations.map(o => ({
                time: o.timestamp,
                test: o.test.description,
                status: o.response?.status,
                unexpected: o.unexpected
            })),
            recommendations: this.generateRecommendations()
        };
    }

    generateRecommendations() {
        const recs = [];

        if (this.issues.some(i => i.severity === 'critical')) {
            recs.push('🔴 Critical issues found - stop and fix before continuing');
        }

        if (this.questions.length > 3) {
            recs.push('❓ Multiple questions raised - schedule follow-up session');
        }

        if (this.observations.length < 10) {
            recs.push('🔍 Session was low-activity - consider more structured approach');
        }

        return recs;
    }
}

// Example usage
async function runExploratorySession() {
    const session = new ExploratorySession({
        title: 'Authentication Boundaries',
        mission: 'Explore the login endpoint with various password formats to discover how it handles edge cases',
        timebox: 30,
        areas: ['password length', 'special characters', 'unicode', 'rate limiting']
    });

    session.start();
    await session.explore();

    const report = session.generateReport();
    console.log(JSON.stringify(report, null, 2));

    return report;
}
