Edge cases are where most bugs live. They're the inputs, conditions, and sequences that developers didn't think about.

**Categories of Edge Cases**:

| Category | Description | Examples |
|----------|-------------|----------|
| **Boundary** | At or just beyond limits | Min-1, Max+1, empty, null |
| **Combinatorial** | Unusual combinations | Valid + invalid, multiple errors |
| **Temporal** | Time-based | Leap years, timezone boundaries |
| **Sequential** | Operation order | Delete then get, update then delete |
| **Environmental** | System conditions | Low memory, high load |
| **Data** | Unusual data | Unicode, very long, binary |

**Edge Case Discovery Techniques**:

```javascript
// edge-case-discovery.js
class EdgeCaseDiscoverer {
    constructor(api) {
        this.api = api;
        this.edgeCases = [];
    }

    // 1. Boundary Analysis
    async exploreBoundaries(endpoint, param, min, max) {
        const boundaries = [
            { value: min - 1, description: 'Below minimum' },
            { value: min, description: 'At minimum' },
            { value: min + 1, description: 'Above minimum' },
            { value: max - 1, description: 'Below maximum' },
            { value: max, description: 'At maximum' },
            { value: max + 1, description: 'Above maximum' },
            { value: null, description: 'Null value' },
            { value: undefined, description: 'Undefined' },
            { value: '', description: 'Empty string' },
            { value: ' ', description: 'Whitespace' }
        ];

        for (const boundary of boundaries) {
            const response = await this.api.request(endpoint, {
                [param]: boundary.value
            });

            if (this.isUnexpected(response, boundary)) {
                this.edgeCases.push({
                    endpoint,
                    param,
                    value: boundary.value,
                    description: boundary.description,
                    response: response
                });
            }
        }
    }

    // 2. Combinatorial Testing
    async exploreCombinations(endpoint, params) {
        const combinations = this.generateCombinations(params);

        for (const combo of combinations) {
            const response = await this.api.request(endpoint, combo);

            if (this.hasUnexpectedInteraction(response, combo)) {
                this.edgeCases.push({
                    endpoint,
                    combination: combo,
                    response
                });
            }
        }
    }

    // 3. Sequence Testing
    async exploreSequences(operations) {
        const sequences = this.generateSequences(operations);

        for (const sequence of sequences) {
            const results = [];
            let failed = false;

            for (const op of sequence) {
                const result = await this.api.request(op.endpoint, op.data);
                results.push(result);

                if (result.status >= 500) {
                    failed = true;
                    break;
                }
            }

            if (failed) {
                this.edgeCases.push({
                    sequence,
                    results,
                    failurePoint: results.length
                });
            }
        }
    }

    // 4. Fuzzing
    async fuzz(endpoint, iterations = 1000) {
        for (let i = 0; i < iterations; i++) {
            const fuzzedData = this.generateFuzzData();

            try {
                const response = await this.api.request(endpoint, fuzzedData);

                if (response.status >= 500) {
                    this.edgeCases.push({
                        type: 'fuzzing',
                        iteration: i,
                        data: fuzzedData,
                        response: response
                    });
                }
            } catch (error) {
                // Request completely failed - interesting!
                this.edgeCases.push({
                    type: 'fuzzing_crash',
                    iteration: i,
                    data: fuzzedData,
                    error: error.message
                });
            }
        }
    }

    generateFuzzData() {
        // Generate random, potentially malformed data
        const types = ['string', 'number', 'array', 'object', 'null', 'boolean'];
        const type = types[Math.floor(Math.random() * types.length)];

        switch(type) {
            case 'string':
                return this.randomString(100);
            case 'number':
                return Math.random() * 1000000;
            case 'array':
                return [this.generateFuzzData(), this.generateFuzzData()];
            case 'object':
                return {
                    [this.randomString(10)]: this.generateFuzzData()
                };
            case 'null':
                return null;
            case 'boolean':
                return Math.random() > 0.5;
        }
    }
}
```

