**Session Metrics Dashboard**:

```javascript
class SessionDashboard {
    constructor(sessions) {
        this.sessions = sessions;
    }

    calculateTeamMetrics() {
        const totalSessions = this.sessions.length;
        const totalFindings = this.sessions.reduce((sum, s) => sum + s.findings.length, 0);
        const totalTime = this.sessions.reduce((sum, s) => sum + (s.duration || 0), 0);

        const findingsBySeverity = this.sessions.reduce((acc, session) => {
            session.findings.forEach(finding => {
                acc[finding.severity] = (acc[finding.severity] || 0) + 1;
            });
            return acc;
        }, {});

        return {
            totalSessions,
            totalFindings,
            totalTime: `${Math.round(totalTime)} minutes`,
            avgFindingsPerSession: (totalFindings / totalSessions).toFixed(1),
            findingsPerHour: ((totalFindings / totalTime) * 60).toFixed(1),
            findingsBySeverity,
            topTesters: this.getTopTesters(),
            trend: this.calculateTrend()
        };
    }

    getTopTesters() {
        const testerStats = {};

        this.sessions.forEach(session => {
            const tester = session.charter?.tester || 'Unknown';
            if (!testerStats[tester]) {
                testerStats[tester] = { sessions: 0, findings: 0 };
            }
            testerStats[tester].sessions++;
            testerStats[tester].findings += session.findings.length;
        });

        return Object.entries(testerStats)
            .map(([name, stats]) => ({ name, ...stats }))
            .sort((a, b) => b.findings - a.findings);
    }

    calculateTrend() {
        // Sort sessions by date
        const sorted = [...this.sessions].sort((a, b) => 
            new Date(a.startTime) - new Date(b.startTime)
        );

        // Calculate moving average of findings per session
        const windowSize = 3;
        const trend = [];

        for (let i = 0; i < sorted.length; i++) {
            const start = Math.max(0, i - windowSize + 1);
            const window = sorted.slice(start, i + 1);
            const avgFindings = window.reduce((sum, s) => sum + s.findings.length, 0) / window.length;
            trend.push({
                session: i + 1,
                avgFindings: avgFindings.toFixed(1)
            });
        }

        return trend;
    }
}
