    const results = await api.sequence([
        { method: 'post', path: '/users', data: { name: 'Test User' }, saveAs: 'newUser' },
        { method: 'get', path: `/users/${api.variables.newUser?.id}` },
        { method: 'put', path: `/users/${api.variables.newUser?.id}`, data: { name: 'Updated' } },
        { method: 'delete', path: `/users/${api.variables.newUser?.id}` },
        { method: 'get', path: `/users/${api.variables.newUser?.id}` } // Should 404
    ]);

    console.log('Sequence complete', results.map(r => r.response?.status));
}

async function exploreParallel() {
