        const errorScenarios = [
            { method: 'get', url: '/users/999999', expected: 404 },
            { method: 'post', url: '/users', data: {}, expected: 400 },
            { method: 'get', url: '/users/me', expected: 401 }
        ];

        for (const scenario of errorScenarios) {
            const v1Response = await request('https://api-v1.example.com')
                [scenario.method](scenario.url)
                .send(scenario.data || {});

            const v2Response = await request('https://api-v2.example.com')
                [scenario.method](scenario.url)
                .send(scenario.data || {});

            expect(v2Response.status).toBe(v1Response.status);
        }
    });
});
