// usability/response-consistency.js
describe('Response Structure Consistency', () => {
    const endpoints = [
        { method: 'get', path: '/users/1' },
        { method: 'get', path: '/products/1' },
        { method: 'get', path: '/orders/1' },
        { method: 'post', path: '/users', data: { name: 'Test' } }
    ];

    it('uses consistent error format across endpoints', async () => {
