            request('https://api.example.com').get('/users/999999'),
            request('https://api.example.com').post('/users').send({}),
            request('https://api.example.com').get('/products/999999'),
            request('https://api.example.com').get('/unauthorized')
        ]);

        errorResponses.forEach(response => {
            if (response.status >= 400) {
                // All errors should have same structure
                expect(response.body.error).toBeDefined();
                expect(response.body.error.code).toBeDefined();
                expect(response.body.error.message).toBeDefined();

                // Optional but good to have
                if (response.body.error.details) {
                    expect(typeof response.body.error.details).toBe('object');
                }
                if (response.body.error.timestamp) {
                    expect(new Date(response.body.error.timestamp)).toBeInstanceOf(Date);
                }
            }
        });
    });

    it('uses consistent success response wrapper', async () => {
