```javascript
// usability/first-guess.js
describe('First-Guess Intuitiveness Tests', () => {
    // These tests simulate what a developer might try first

    const baseURL = 'https://api.example.com';

    it('GET /user (singular) should not work', async () => {
        // Developer might try singular first
        const response = await request(baseURL)
            .get('/user')
            .set('Authorization', `Bearer ${testToken}`);

        // Should either 404 or redirect
        expect([404, 301, 308]).toContain(response.status);

        if (response.status === 404) {
            // Should suggest plural
            expect(response.body.error?.message || '').toMatch(/did you mean.*users/i);
        }

        if (response.status === 301 || response.status === 308) {
            // Should redirect to plural
            expect(response.headers.location).toContain('/users');
        }
    });

    it('GET /orders?id=123 should not work', async () => {
        // Developer might try query param for single resource
        const response = await request(baseURL)
            .get('/orders')
            .query({ id: 123 })
            .set('Authorization', `Bearer ${testToken}`);

        // Should either 404 or return collection (if id is filter)
        if (response.status === 200) {
            // If it returns a collection, should have helpful message
            expect(response.body._links?.self).toBeDefined();
        } else {
            expect([404, 400]).toContain(response.status);
            if (response.status === 400) {
                expect(response.body.error.message).toMatch(/use.*\/orders\/\d+/i);
            }
        }
    });

    it('PUT /users should not create', async () => {
        // Developer might try PUT to create
        const response = await request(baseURL)
            .put('/users')
            .set('Authorization', `Bearer ${testToken}`)
            .send({ name: 'Test User', email: 'test@example.com' });

        // Should either 405 or 404
        expect([405, 404]).toContain(response.status);

        if (response.status === 405) {
            // Should include Allow header with POST
            expect(response.headers['allow']).toContain('POST');
        }
    });

    it('POST /users/123/delete should not work', async () => {
        // Developer might try RPC-style delete
        const response = await request(baseURL)
            .post('/users/123/delete')
            .set('Authorization', `Bearer ${testToken}`);

        // Should either 404 or redirect to DELETE
        expect([404, 405]).toContain(response.status);

        if (response.status === 405) {
            expect(response.headers['allow']).toContain('DELETE');
        }
    });
});
