// usability/error-recovery.js
describe('Error Recovery Workflow', () => {
    it('developer can understand and fix validation errors', async () => {
        // First attempt - will fail
        const badResponse = await request('https://api.example.com')
            .post('/users')
            .set('Authorization', `Bearer ${apiKey}`)
            .send({
                // Missing required fields
                name: ''
            });

        expect(badResponse.status).toBe(400);

        // Error should clearly indicate what's wrong
        const error = badResponse.body.error || badResponse.body;
        expect(error.details || error.message).toBeDefined();

        // Developer should be able to fix based on error
        const goodResponse = await request('https://api.example.com')
            .post('/users')
            .set('Authorization', `Bearer ${apiKey}`)
            .send({
                name: 'Fixed User',
                email: 'fixed@example.com'
            });

        expect(goodResponse.status).toBe(201);
    });

    it('developer can handle rate limits gracefully', async () => {
        // This test would simulate hitting rate limits
        // and verify that retry logic works

        // Make many requests quickly
        const responses = [];
        for (let i = 0; i < 100; i++) {
            responses.push(
                request('https://api.example.com')
                    .get('/public')
                    .set('Authorization', `Bearer ${apiKey}`)
            );
        }

        const results = await Promise.allSettled(responses);

        // Some should be rate limited
        const rateLimited = results.filter(r => 
            r.value?.status === 429
        );

        if (rateLimited.length > 0) {
            // Rate limit response should include retry info
            const rateLimitResponse = rateLimited[0].value;
            expect(rateLimitResponse.headers['retry-after']).toBeDefined();

            // Error message should explain rate limits
            expect(rateLimitResponse.body.error?.message || '')
                .toMatch(/rate|limit|too many/i);
        }
    });
});
