K6 is a developer-centric performance testing tool that uses JavaScript for test scripts. It's designed for CI/CD integration and has a strong focus on metrics.

**K6 Test Structure**:

```javascript
// k6-test.js
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';

// Custom metrics
const errorRate = new Rate('errors');
const requestDuration = new Trend('request_duration');

// Test configuration
export const options = {
    stages: [
        { duration: '1m', target: 10 },  // Ramp up to 10 users
        { duration: '3m', target: 10 },  // Stay at 10 users
        { duration: '1m', target: 0 },   // Ramp down to 0
    ],
    thresholds: {
        http_req_duration: ['p(95)<500', 'p(99)<1000'], // 95% <500ms, 99% <1s
        http_req_failed: ['rate<0.01'],                 // <1% errors
        errors: ['rate<0.05'],                           // Custom metric threshold
    },
};

// Setup function (runs once)
export function setup() {
    // Create test data, get auth tokens, etc.
    const loginRes = http.post('https://api.example.com/auth/login', {
        username: 'testuser',
        password: 'testpass',
    });

    return {
        token: loginRes.json('token'),
        userId: loginRes.json('userId'),
    };
}

// Main test function (runs for each VU iteration)
export default function(data) {
    // Use data from setup
    const params = {
        headers: {
            'Authorization': `Bearer ${data.token}`,
            'Content-Type': 'application/json',
        },
    };

    // GET request
    const getRes = http.get(
        `https://api.example.com/users/${data.userId}`,
        params
    );

    // Check response
    check(getRes, {
        'status is 200': (r) => r.status === 200,
        'has user data': (r) => r.json('id') !== undefined,
    });

    // Track custom metric
    requestDuration.add(getRes.timings.duration);
    errorRate.add(getRes.status >= 400);

    // POST request
    const payload = JSON.stringify({
        name: 'Updated Name',
        email: 'updated@example.com',
    });

    const putRes = http.put(
        `https://api.example.com/users/${data.userId}`,
        payload,
        params
    );

    check(putRes, {
        'update successful': (r) => r.status === 200,
    });

    // Think time between requests
    sleep(1);
}

// Teardown function (runs once after test)
export function teardown(data) {
    // Clean up test data
    http.del(`https://api.example.com/users/${data.userId}`, null, {
        headers: { 'Authorization': `Bearer ${data.token}` },
    });
}
