    check(response, {
        'status is 2xx': (r) => r.status >= 200 && r.status < 300,
        'status is not 5xx': (r) => r.status < 500,
    });

    errorRate.add(response.status >= 400);

    // No think time under stress - maximum load
    // sleep(0);
}

// Custom check to find breaking point
export function handleSummary(data) {
    // Analyze at which point failures started
    const points = data.metrics.http_req_failed.values;

    let breakingPoint = null;
    for (let i = 0; i < points.length; i++) {
        if (points[i].value > 0.05) { // 5% error rate threshold
            breakingPoint = points[i].time;
            break;
        }
    }

    return {
        'stdout': textSummary(data, { indent: ' ', enableColors: true }),
        'stress-results.json': JSON.stringify({
            breakingPoint,
            maxUsers: data.metrics.vus_max.values.value,
