**Stress Test Results Analysis**:

```javascript
// stress-analysis.js
class StressTestAnalyzer {
    constructor(results) {
        this.results = results;
    }

    findBreakingPoint() {
        // Group results by load level
        const loadLevels = this.groupByLoadLevel();

        let breakingPoint = null;
        let previousErrorRate = 0;
        let previousResponseTime = 0;

        for (const level of loadLevels) {
            const errorRate = this.calculateErrorRate(level.results);
            const responseTime = this.calculateP95(level.results);

            // Look for inflection points
            if (errorRate > 0.05 && previousErrorRate <= 0.05) {
                breakingPoint = {
                    users: level.users,
                    errorRate: errorRate,
                    responseTime: responseTime,
                    type: 'error_rate_spike',
                };
                break;
            }

            if (responseTime > 2000 && previousResponseTime <= 2000) {
                breakingPoint = {
                    users: level.users,
                    errorRate: errorRate,
                    responseTime: responseTime,
                    type: 'latency_spike',
                };
                break;
            }

            previousErrorRate = errorRate;
            previousResponseTime = responseTime;
        }

        return breakingPoint;
    }

    analyzeFailureMode() {
        const breakingPoint = this.findBreakingPoint();
        if (!breakingPoint) {
            return {
                mode: 'no_failure',
                message: 'API survived maximum test load',
            };
        }

        // Analyze how it failed
        const failuresAtBreak = this.results.filter(r => 
            r.loadLevel === breakingPoint.users && r.status >= 500
        );

        const errorTypes = {};
        failuresAtBreak.forEach(f => {
            const errorCode = f.status;
            errorTypes[errorCode] = (errorTypes[errorCode] || 0) + 1;
        });

        // Determine failure mode
        let mode = 'unknown';
        if (errorTypes[503] && errorTypes[503] / failuresAtBreak.length > 0.5) {
            mode = 'graceful_degradation';
        } else if (errorTypes[500] && errorTypes[500] / failuresAtBreak.length > 0.5) {
            mode = 'internal_errors';
        } else if (failuresAtBreak.some(f => f.timedOut)) {
            mode = 'timeouts';
        } else if (failuresAtBreak.some(f => !f.response)) {
            mode = 'connection_refused';
        }

        return {
            mode,
            breakingPoint,
            errorDistribution: errorTypes,
            recommendation: this.getRecommendation(mode),
        };
    }

    getRecommendation(mode) {
        const recommendations = {
            graceful_degradation: '✅ API degrades gracefully - implement circuit breakers and fallbacks',
            internal_errors: '🔴 Internal errors at limit - check for exceptions, add error handling',
            timeouts: '⏰ Timeouts at limit - optimize slow queries, add timeouts, consider async',
            connection_refused: '🔌 Connection refused - server overloaded, scale up, add load balancing',
            no_failure: '🎉 Excellent - consider increasing test limits',
        };

        return recommendations[mode] || 'Investigate failure mode';
    }

    calculateMaxCapacity() {
        const loadLevels = this.groupByLoadLevel();

        // Find the last level with acceptable performance
        let maxCapacity = null;
        for (const level of loadLevels) {
            const errorRate = this.calculateErrorRate(level.results);
            const responseTime = this.calculateP95(level.results);

            if (errorRate <= 0.01 && responseTime <= 1000) {
                maxCapacity = level.users;
            } else {
                break;
            }
        }

        return maxCapacity;
    }

    generateStressReport() {
        const breakingPoint = this.findBreakingPoint();
        const failureMode = this.analyzeFailureMode();
        const maxCapacity = this.calculateMaxCapacity();

        return {
            summary: {
                maxLoadTested: Math.max(...this.results.map(r => r.loadLevel)),
                maxCapacity: maxCapacity,
                breakingPoint: breakingPoint,
                failureMode: failureMode.mode,
            },
            recommendations: [
                failureMode.recommendation,
                maxCapacity ? `📊 Safe operating capacity: ${maxCapacity} concurrent users` : '⚠️ Unable to determine safe capacity',
                breakingPoint ? `💥 Breaking point: ${breakingPoint.users} users with ${(breakingPoint.errorRate*100).toFixed(1)}% errors` : '✅ No breaking point found',
            ],
            details: failureMode,
        };
    }
}
```

**Stress Testing Best Practices**:

| Practice | Why | How |
|----------|-----|-----|
| **Increment Gradually** | Find exact breaking point | Small load increments |
| **Monitor Everything** | Identify first bottleneck | Watch CPU, memory, DB, network |
| **Test Auto-scaling** | Verify scaling triggers | Include scale-up in test |
| **Know Your Limits** | Plan capacity | Document maximums |
| **Test Recovery** | Does it come back? | Ramp down after stress |
| **Document Failure Mode** | Be prepared | Know what to expect |

**Key Insight**: Stress testing isn't about avoiding failure—it's about understanding how your API fails. Graceful degradation is better than catastrophic crash.

Spike testing simulates sudden, dramatic increases in traffic. It answers: "What happens when we get slashdotted, go viral, or have a marketing campaign?"

**Spike Testing Goals**:

✅ Handle sudden traffic surges
✅ Verify auto-scaling responsiveness
✅ Test queue/buffer mechanisms
✅ Ensure no cascading failures
✅ Measure recovery time
✅ Prevent total outage

**K6 Spike Test Example**:

```javascript
// spike-test.js
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const errorRate = new Rate('errors');
