package simulations

import io.gatling.core.Predef._
import io.gatling.http.Predef._
import scala.concurrent.duration._

class SpikeSimulation extends Simulation {

  val httpProtocol = http
    .baseUrl("https://api.example.com")
    .acceptHeader("application/json")
    .userAgentHeader("Gatling Spike Test")

  // Hot content scenario (what everyone wants during spike)
  val hotContentScenario = scenario("Hot Content")
    .exec(
      http("Get Hot Product")
        .get("/products/hot-deal")
        .check(
          status.is(200),
          responseTimeInMillis.lte(3000)
        )
    )

  // Normal traffic scenario (background noise)
  val normalTrafficScenario = scenario("Normal Traffic")
    .feed(csv("users.csv").random)
    .exec(
      http("Get Random Product")
        .get("/products/${userId}")
        .check(status.is(200))
    )
    .pause(2.seconds, 5.seconds)

  setUp(
    // Normal background traffic
    normalTrafficScenario.inject(
      constantUsersPerSec(10).during(10.minutes) // 10 RPS background
    ),

    // SPIKE! 100x increase in 10 seconds
    hotContentScenario.inject(
      nothingFor(5.minutes), // Wait for baseline
      rampUsersPerSec(10).to(1000).during(10.seconds), // SPIKE
      constantUsersPerSec(1000).during(30.seconds), // Hold spike
      rampUsersPerSec(1000).to(10).during(30.seconds) // Recovery
    )
  ).protocols(httpProtocol)
    .assertions(
      // During spike, we tolerate higher latency but no failures
      forAll.responseTime.percentile3.lte(5000), // p95 < 5s during spike
      global.failedRequests.percent.lte(5) // <5% errors during spike
    )
}
