**Key Insight**: Spikes test not just capacity, but responsiveness. Can your API scale up fast enough to meet demand, and scale down to save costs afterward?

Soak testing (also called endurance testing) runs sustained load over hours or days to detect issues that only appear over time: memory leaks, connection leaks, resource exhaustion, and performance degradation.

**Soak Testing Goals**:

✅ Detect memory leaks
✅ Find connection/resource leaks
✅ Identify performance degradation
✅ Verify garbage collection behavior
✅ Test for database connection limits
✅ Ensure long-term stability

**K6 Soak Test Example**:

```javascript
// soak-test.js
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Trend, Rate } from 'k6/metrics';

// Custom metrics to track over time
const requestDuration = new Trend('request_duration');
const errorRate = new Rate('errors');
const memoryUsage = new Trend('memory_usage'); // If using k6 extensions

export const options = {
    stages: [
        { duration: '10m', target: 100 },  // Ramp up to 100 users
        { duration: '24h', target: 100 },  // Stay at 100 users for 24 HOURS
        { duration: '10m', target: 0 },    // Ramp down
    ],
    thresholds: {
        // Over 24 hours, we expect consistent performance
        http_req_duration: ['p(95)<1000', 'p(99)<2000'],
        http_req_failed: ['rate<0.01'],
        // Check for degradation over time
        'http_req_duration': [
            { threshold: 'p(95)<800', abortOnFail: false }, // Alert if threshold exceeded
        ],
    },
};

// Track performance over time to detect degradation
const hourlyStats = [];

export default function() {
    const params = {
        headers: {
            'Authorization': `Bearer ${__ENV.API_KEY}`,
            'Content-Type': 'application/json',
        },
    };

    const response = http.get('https://api.example.com/users/123', params);

    check(response, {
        'status is 200': (r) => r.status === 200,
    });

    requestDuration.add(response.timings.duration);
    errorRate.add(response.status >= 400);

    // Log hourly stats for trend analysis
    const currentHour = Math.floor(Date.now() / (60 * 60 * 1000));
    if (!hourlyStats[currentHour]) {
        hourlyStats[currentHour] = {
            hour: currentHour,
            durations: [],
            errors: 0,
            count: 0,
        };
    }

    hourlyStats[currentHour].durations.push(response.timings.duration);
    hourlyStats[currentHour].count++;
    if (response.status >= 400) {
        hourlyStats[currentHour].errors++;
    }

    // Realistic think time
    sleep(Math.random() * 5 + 2);
}

export function handleSummary(data) {
    // Analyze trends over time
    const trends = [];
    for (let hour = 0; hour < hourlyStats.length; hour++) {
        const stat = hourlyStats[hour];
        if (stat && stat.count > 0) {
            const sorted = stat.durations.sort((a, b) => a - b);
            const p95 = sorted[Math.floor(stat.durations.length * 0.95)];

            trends.push({
                hour,
                avg: stat.durations.reduce((a, b) => a + b, 0) / stat.durations.length,
                p95,
                errorRate: stat.errors / stat.count,
            });
        }
    }

    // Check for degradation
    let degradation = null;
    if (trends.length > 2) {
        const firstHour = trends[0];
        const lastHour = trends[trends.length - 1];

        const p95Increase = ((lastHour.p95 - firstHour.p95) / firstHour.p95) * 100;

        if (p95Increase > 20) {
            degradation = {
                type: 'latency',
                increase: p95Increase,
                from: firstHour.p95,
                to: lastHour.p95,
            };
        }

        const errorRateIncrease = ((lastHour.errorRate - firstHour.errorRate) / firstHour.errorRate) * 100;

        if (errorRateIncrease > 50) {
            degradation = {
                type: 'errors',
                increase: errorRateIncrease,
                from: firstHour.errorRate,
                to: lastHour.errorRate,
            };
        }
    }

    return {
        'soak-results.json': JSON.stringify({
            duration: '24h',
            totalRequests: data.metrics.http_reqs.values.count,
            avgRPS: data.metrics.http_reqs.values.rate,
            overallP95: data.metrics.http_req_duration.values['p(95)'],
            overallErrorRate: data.metrics.http_req_failed.values.rate,
            hourlyTrends: trends,
            degradation: degradation,
            passed: degradation === null,
        }),
    };
}
