**Soak Test Results Analysis**:

```javascript
// soak-analysis.js
class SoakTestAnalyzer {
    constructor(results) {
        this.results = results;
        this.hourlyData = this.aggregateHourly();
    }

    aggregateHourly() {
        const hourly = {};

        this.results.forEach(r => {
            const hour = new Date(r.timestamp).setMinutes(0, 0, 0);
            if (!hourly[hour]) {
                hourly[hour] = {
                    hour,
                    durations: [],
                    errors: 0,
                    total: 0,
                };
            }
            hourly[hour].durations.push(r.duration);
            hourly[hour].total++;
            if (r.status >= 400) {
                hourly[hour].errors++;
            }
        });

        return Object.values(hourly).map(h => ({
            hour: new Date(h.hour).toISOString(),
            avgLatency: h.durations.reduce((a, b) => a + b, 0) / h.durations.length,
            p95Latency: this.percentile(h.durations, 95),
            errorRate: h.errors / h.total,
            throughput: h.total,
        })).sort((a, b) => new Date(a.hour) - new Date(b.hour));
    }

    detectMemoryLeak() {
        // Check if latency or error rate increases over time
        if (this.hourlyData.length < 2) return null;

        const firstHour = this.hourlyData[0];
        const lastHour = this.hourlyData[this.hourlyData.length - 1];

        const latencyIncrease = ((lastHour.p95Latency - firstHour.p95Latency) / firstHour.p95Latency) * 100;
        const errorIncrease = ((lastHour.errorRate - firstHour.errorRate) / firstHour.errorRate) * 100;

        return {
            latencyIncrease: `${latencyIncrease.toFixed(1)}%`,
            errorIncrease: `${errorIncrease.toFixed(1)}%`,
            possibleLeak: latencyIncrease > 20 || errorIncrease > 50,
        };
    }

    findDegradationPoint() {
        // Find when performance started degrading
        const baseline = this.hourlyData.slice(0, 6); // First 6 hours

        if (baseline.length === 0) return null;

        const baselineAvgLatency = baseline.reduce((sum, h) => sum + h.avgLatency, 0) / baseline.length;
        const baselineErrorRate = baseline.reduce((sum, h) => sum + h.errorRate, 0) / baseline.length;

        for (let i = 6; i < this.hourlyData.length; i++) {
            const hour = this.hourlyData[i];
            if (hour.avgLatency > baselineAvgLatency * 1.2 || 
                hour.errorRate > baselineErrorRate * 2) {
                return {
                    hour: hour.hour,
                    latency: hour.avgLatency,
                    baselineLatency: baselineAvgLatency,
                    errorRate: hour.errorRate,
                    baselineErrorRate: baselineErrorRate,
                };
            }
        }

        return null;
    }

    generateSoakReport() {
        const leakAnalysis = this.detectMemoryLeak();
        const degradationPoint = this.findDegradationPoint();

        return {
            summary: {
                testDuration: `${this.hourlyData.length} hours`,
                totalRequests: this.results.length,
                overallAvgLatency: this.results.reduce((sum, r) => sum + r.duration, 0) / this.results.length,
                overallP95: this.percentile(this.results.map(r => r.duration), 95),
                overallErrorRate: this.results.filter(r => r.status >= 400).length / this.results.length,
            },
            trends: {
                latency: leakAnalysis.latencyIncrease,
                errors: leakAnalysis.errorIncrease,
                memoryLeakPossible: leakAnalysis.possibleLeak,
            },
            degradation: degradationPoint,
            hourlyData: this.hourlyData,
            passed: !leakAnalysis.possibleLeak && !degradationPoint,
            recommendations: this.generateRecommendations(leakAnalysis, degradationPoint),
        };
    }

    generateRecommendations(leakAnalysis, degradationPoint) {
        const recs = [];

        if (leakAnalysis.possibleLeak) {
            recs.push('🔴 Possible memory or resource leak detected - investigate with profiling tools');
        }

        if (degradationPoint) {
            recs.push(`⚠️ Performance degraded after ${degradationPoint.hour} - investigate what changed`);
        }

        if (this.results.filter(r => r.status >= 500).length > 0) {
            recs.push('❌ Server errors occurred during soak - check error logs');
        }

        if (recs.length === 0) {
            recs.push('✅ No issues detected - API is stable over long periods');
        }

        return recs;
    }
}
