**Scalability Analysis**:

```javascript
// scalability-analysis.js
class ScalabilityAnalyzer {
    constructor(results) {
        this.results = results;
    }

    analyzeScaling() {
        const points = this.groupByLoadLevel();

        // Calculate scaling factors
        const analysis = {
            points,
            factors: [],
            bottlenecks: [],
            recommendation: '',
        };

        for (let i = 1; i < points.length; i++) {
            const userRatio = points[i].users / points[i-1].users;
            const throughputRatio = points[i].throughput / points[i-1].throughput;
            const latencyRatio = points[i].p95Latency / points[i-1].p95Latency;

            analysis.factors.push({
                stage: `${points[i-1].users} → ${points[i].users}`,
                userIncrease: userRatio,
                throughputIncrease: throughputRatio,
                latencyIncrease: latencyRatio,
                scalingFactor: throughputRatio / userRatio,
            });

            // Detect bottlenecks
            if (throughputRatio / userRatio < 0.7) {
                analysis.bottlenecks.push({
                    at: points[i].users,
                    reason: 'Throughput not keeping up with user increase',
                    scalingFactor: throughputRatio / userRatio,
                });
            }

            if (latencyRatio > 1.5) {
                analysis.bottlenecks.push({
                    at: points[i].users,
                    reason: 'Latency increased significantly',
                    increase: `${((latencyRatio - 1) * 100).toFixed(0)}%`,
                });
            }
        }

        // Determine scaling type
        const avgFactor = analysis.factors.reduce((sum, f) => sum + f.scalingFactor, 0) / analysis.factors.length;

        if (avgFactor > 0.9) {
            analysis.scalingType = 'linear';
            analysis.recommendation = '✅ Excellent linear scaling - architecture scales well';
        } else if (avgFactor > 0.7) {
            analysis.scalingType = 'good';
            analysis.recommendation = '👍 Good scaling - optimize bottlenecks to improve';
        } else if (avgFactor > 0.5) {
            analysis.scalingType = 'fair';
            analysis.recommendation = '⚠️ Fair scaling - investigate bottlenecks';
        } else {
            analysis.scalingType = 'poor';
            analysis.recommendation = '🔴 Poor scaling - major architectural issues';
        }

        return analysis;
    }

    groupByLoadLevel() {
        const levels = {};

        this.results.forEach(r => {
            if (!levels[r.loadLevel]) {
                levels[r.loadLevel] = {
                    users: r.loadLevel,
                    durations: [],
                    count: 0,
                };
            }
            levels[r.loadLevel].durations.push(r.duration);
            levels[r.loadLevel].count++;
        });

        return Object.values(levels).map(l => ({
            users: l.users,
            throughput: l.count / this.calculateTestDuration(l),
            p95Latency: this.percentile(l.durations, 95),
            avgLatency: l.durations.reduce((a, b) => a + b, 0) / l.durations.length,
        })).sort((a, b) => a.users - b.users);
    }

    predictCapacity(targetLatency) {
        // Use regression to predict capacity at target latency
        const points = this.groupByLoadLevel();

        // Simple linear regression on log-transformed data
        const logPoints = points.map(p => ({
            x: Math.log(p.users),
            y: Math.log(p.p95Latency),
        }));

        // Fit line y = a + bx
        const n = logPoints.length;
        const sumX = logPoints.reduce((s, p) => s + p.x, 0);
        const sumY = logPoints.reduce((s, p) => s + p.y, 0);
        const sumXY = logPoints.reduce((s, p) => s + p.x * p.y, 0);
        const sumXX = logPoints.reduce((s, p) => s + p.x * p.x, 0);

        const b = (n * sumXY - sumX * sumY) / (n * sumXX - sumX * sumX);
        const a = (sumY - b * sumX) / n;

        // Predict users at target latency
        const logTarget = Math.log(targetLatency);
        const logUsers = (logTarget - a) / b;
        const predictedUsers = Math.exp(logUsers);

        return Math.round(predictedUsers);
    }

    generateScalabilityReport() {
        const analysis = this.analyzeScaling();
        const capacity = this.predictCapacity(1000); // Predict at 1000ms target

        return {
            summary: {
                scalingType: analysis.scalingType,
                averageScalingFactor: analysis.factors.reduce((sum, f) => sum + f.scalingFactor, 0) / analysis.factors.length,
                bottlenecksFound: analysis.bottlenecks.length,
                predictedCapacityAt1s: capacity,
            },
            details: analysis,
            bottlenecks: analysis.bottlenecks,
            recommendation: analysis.recommendation,
        };
    }
}
