// performance-dashboard.js
class PerformanceDashboard {
    constructor() {
        this.history = [];
    }

    async addRun(results) {
        this.history.push({
            timestamp: new Date().toISOString(),
            commit: process.env.GITHUB_SHA,
            branch: process.env.GITHUB_REF,
            ...results,
        });

        await this.saveHistory();
    }

    generateDashboard() {
        const recent = this.history.slice(-30); // Last 30 runs

        const trends = {
            latency: this.calculateTrend(recent.map(r => r.p95Latency)),
            throughput: this.calculateTrend(recent.map(r => r.throughput)),
            errors: this.calculateTrend(recent.map(r => r.errorRate)),
        };

        const alerts = [];

        // Check for degrading trends
        if (trends.latency > 5) {
            alerts.push('⚠️ Latency increasing over last 30 runs');
        }

        if (trends.errors > 10) {
            alerts.push('⚠️ Error rate trending up');
        }

        if (trends.throughput < -10) {
            alerts.push('⚠️ Throughput decreasing');
        }

        return {
            summary: {
                lastRun: this.history[this.history.length - 1],
                trends,
                alerts,
                passingRate: this.calculatePassingRate(),
            },
            history: this.history,
            charts: this.generateChartData(),
        };
    }

    calculateTrend(values) {
        if (values.length < 10) return 0;

        const first = values.slice(0, 5).reduce((a, b) => a + b, 0) / 5;
        const last = values.slice(-5).reduce((a, b) => a + b, 0) / 5;

        return ((last - first) / first) * 100;
    }

    calculatePassingRate() {
        const passing = this.history.filter(r => r.passed).length;
        return (passing / this.history.length) * 100;
    }
}
