**Key Insight:** Grammar-based fuzzing builds strings by expanding rules recursively. Each token in a production is either a literal string (added directly) or a non-terminal symbol (expanded further). This creates syntactically valid inputs that can find deep parsing bugs.

Chaos engineering is the discipline of experimenting on a system to build confidence in its capability to withstand turbulent conditions. For APIs, this means injecting failures and observing behavior.

**Chaos Engineering Principles:**

```
┌─────────────────────────────────────────────────────────────────┐
│                    CHAOS ENGINEERING PRINCIPLES                   │
├─────────────────────────────────────────────────────────────────┤
│                                                                   │
│  1. Build a Hypothesis: "The API will return 5xx errors when     │
│     the database is down, not hang indefinitely."                │
│                                                                   │
│  2. Define Blast Radius: Start small, test in staging first      │
│                                                                   │
│  3. Run the Experiment: Inject failure, observe behavior         │
│                                                                   │
│  4. Prove or Disprove: Did the system behave as expected?        │
│                                                                   │
│  5. Automate: Run experiments continuously                       │
│                                                                   │
└─────────────────────────────────────────────────────────────────┘
```

**Types of Chaos Experiments:**

| Experiment | Description | Tool |
|------------|-------------|------|
| **Latency injection** | Add delay to responses | Toxiproxy, Chaos Monkey |
| **Error injection** | Return 5xx errors | Custom middleware |
| **Service outage** | Take downstream services down | Kubernetes, Docker |
| **Resource exhaustion** | CPU, memory, disk pressure | stress-ng |
| **Network problems** | Packet loss, corruption | tc (traffic control) |

**Latency Injection Proxy:**

```javascript
// chaos/latency-proxy.js
const http = require('http');
const httpProxy = require('http-proxy');

class ChaosProxy {
  constructor(targetPort, chaosPort) {
    this.targetPort = targetPort;
    this.chaosPort = chaosPort;
    this.proxy = httpProxy.createProxyServer({});
    this.latency = 0;
    this.errorRate = 0;
    this.server = null;
  }

  start() {
    this.server = http.createServer((req, res) => {
      // Random error injection
      if (Math.random() < this.errorRate) {
        res.writeHead(500, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ 
          error: 'Chaos injected',
          message: 'This is a simulated failure'
        }));
        return;
      }

      // Latency injection
      setTimeout(() => {
        this.proxy.web(req, res, {
          target: `http://localhost:${this.targetPort}`
        });
      }, this.latency);
    });

    this.server.listen(this.chaosPort, () => {
      console.log(`Chaos proxy listening on port ${this.chaosPort}`);
      console.log(`Target: localhost:${this.targetPort}`);
    });
  }

  setLatency(ms) {
    this.latency = ms;
    console.log(`Latency set to ${ms}ms`);
  }

  setErrorRate(rate) {
    this.errorRate = rate;
    console.log(`Error rate set to ${rate * 100}%`);
  }

  reset() {
    this.latency = 0;
    this.errorRate = 0;
    console.log('Chaos settings reset');
  }

  stop() {
    if (this.server) {
      this.server.close();
    }
  }
}

// Usage
const proxy = new ChaosProxy(3000, 3001);
proxy.start();

// In another process, send commands via HTTP
const express = require('express');
const app = express();
app.use(express.json());

app.post('/chaos/latency', (req, res) => {
  proxy.setLatency(req.body.ms);
  res.json({ status: 'ok' });
});

app.post('/chaos/error', (req, res) => {
  proxy.setErrorRate(req.body.rate);
  res.json({ status: 'ok' });
});

app.post('/chaos/reset', (req, res) => {
  proxy.reset();
  res.json({ status: 'ok' });
});

app.listen(3002, () => {
  console.log('Chaos control API on port 3002');
});
```

