```javascript
// chaos/database-chaos.js
const { Client } = require('pg');
const axios = require('axios');

class DatabaseChaosExperiment {
  constructor(apiUrl, dbConfig) {
    this.apiUrl = apiUrl;
    this.db = new Client(dbConfig);
  }

  async run() {
    console.log('Starting database chaos experiment...');

    // Baseline measurement
    const baseline = await this.measureBaseline();
    console.log('Baseline:', baseline);

    // Experiment 1: Kill database connections
    await this.experimentKillConnections();

    // Experiment 2: Slow queries
    await this.experimentSlowQueries();

    // Experiment 3: Connection pool exhaustion
    await this.experimentPoolExhaustion();

    console.log('Experiments complete');
  }

  async measureBaseline() {
    const results = [];
    for (let i = 0; i < 10; i++) {
      const start = Date.now();
      await axios.get(`${this.apiUrl}/api/users`);
      results.push(Date.now() - start);
    }
    return {
      avg: results.reduce((a, b) => a + b, 0) / results.length,
      p95: results.sort()[Math.floor(results.length * 0.95)]
    };
  }

  async experimentKillConnections() {
    console.log('\n📊 Experiment: Kill database connections');

    await this.db.connect();

    // Kill all connections except ours
    await this.db.query(`
      SELECT pg_terminate_backend(pid)
      FROM pg_stat_activity
      WHERE pid != pg_backend_pid()
      AND datname = current_database()
    `);

    // Test API behavior
    try {
      const response = await axios.get(`${this.apiUrl}/api/users`, {
        timeout: 5000
      });
      console.log('API responded with:', response.status);
    } catch (error) {
      if (error.code === 'ECONNABORTED') {
        console.log('❌ API timeout - connection recovery failed');
      } else if (error.response) {
        console.log(`API responded with ${error.response.status}:`, 
                    error.response.data);
      }
    }

    await this.db.end();
  }

  async experimentSlowQueries() {
    console.log('\n📊 Experiment: Slow queries');

    // Run slow query in background
    const slowQuery = this.db.query(`
      SELECT * FROM users, generate_series(1, 1000000)
    `);

    // Test API during slow query
    const start = Date.now();
    try {
      await axios.get(`${this.apiUrl}/api/users`, { timeout: 2000 });
      console.log(`API responded in ${Date.now() - start}ms`);
    } catch (error) {
      console.log('API failed:', error.message);
    }

    // Cancel slow query
    await this.db.query('SELECT pg_cancel_backend(pg_backend_pid())');
  }

  async experimentPoolExhaustion() {
    console.log('\n📊 Experiment: Connection pool exhaustion');

    // Create many connections
    const connections = [];
    for (let i = 0; i < 50; i++) {
      const client = new Client(this.dbConfig);
      await client.connect();
      connections.push(client);
    }

    // Test API
    try {
      await axios.get(`${this.apiUrl}/api/users`);
      console.log('✅ API still works with exhausted pool');
    } catch (error) {
      console.log('❌ API failed:', error.message);
    }

    // Clean up
    for (const client of connections) {
      await client.end();
    }
  }
}

// Usage
const experiment = new DatabaseChaosExperiment(
  'http://localhost:3000',
  {
    host: 'localhost',
    port: 5432,
    database: 'test',
    user: 'postgres',
    password: 'password'
  }
);
experiment.run();
