**Key Insight:** Resilience testing verifies that your API fails gracefully. Test not just success cases, but how your system behaves under failure.

Failure injection is the practice of deliberately introducing faults into a system to test its resilience. Here are common patterns and how to implement them.

**Failure Injection Middleware:**

```javascript
// chaos/failure-middleware.js
const failureMiddleware = (options = {}) => {
  return (req, res, next) => {
    // Check if failure should be injected
    if (shouldInjectFailure(req, options)) {
      const failure = selectFailure(options);

      switch (failure.type) {
        case 'latency':
          return setTimeout(next, failure.duration);

        case 'error':
          return res.status(failure.status).json({
            error: 'Injected failure',
            type: failure.type,
            message: failure.message
          });

        case 'crash':
          process.exit(1); // Don't do this in production!

        case 'exception':
          throw new Error(failure.message);

        case 'corrupt-response':
          // Corrupt the response
          const originalJson = res.json;
          res.json = function(data) {
            const corrupted = corruptData(data);
            return originalJson.call(this, corrupted);
          };
          return next();
      }
    }

    next();
  };
};

const shouldInjectFailure = (req, options) => {
  // Check headers for explicit failure request
  if (req.headers['x-failure-type']) {
    return true;
  }

  // Random injection based on rate
  if (options.rate && Math.random() < options.rate) {
    return true;
  }

  // Path-based injection
  if (options.paths && options.paths.includes(req.path)) {
    return true;
  }

  return false;
};

const selectFailure = (options) => {
  const types = options.types || ['latency', 'error'];
  const type = types[Math.floor(Math.random() * types.length)];

  switch (type) {
    case 'latency':
      return {
        type: 'latency',
        duration: options.latency || 1000
      };

    case 'error':
      return {
        type: 'error',
        status: options.status || 500,
        message: options.message || 'Internal Server Error'
      };

    default:
      return { type: 'error', status: 500 };
  }
};

const corruptData = (data) => {
  if (typeof data === 'object') {
    const corrupted = { ...data };
    // Randomly modify fields
    if (corrupted.id) corrupted.id = 'CORRUPTED';
    if (corrupted.name) corrupted.name = corrupted.name.split('').reverse().join('');
    return corrupted;
  }
  return 'CORRUPTED';
};

// Usage in Express
app.use(failureMiddleware({
  rate: 0.1, // 10% of requests
  types: ['latency', 'error', 'corrupt-response'],
  latency: 2000,
  status: 503,
  message: 'Service Unavailable (Chaos)'
}));

// Or via headers for testing
app.get('/api/users', (req, res) => {
  // Check for failure headers
  if (req.headers['x-failure-delay']) {
    setTimeout(() => res.json(users), parseInt(req.headers['x-failure-delay']));
  } else if (req.headers['x-failure-error']) {
    res.status(parseInt(req.headers['x-failure-error']) || 500)
       .json({ error: 'Injected failure' });
  } else {
    res.json(users);
  }
});
```

**Database Failure Injection:**

```javascript
// chaos/db-failure.js
class DatabaseFailureInjector {
  constructor(pool) {
    this.pool = pool;
    this.failureMode = null;
  }

  enableFailure(mode, options = {}) {
    this.failureMode = { mode, options };
    console.log(`Database failure mode enabled: ${mode}`);
  }

  disableFailure() {
    this.failureMode = null;
    console.log('Database failure mode disabled');
  }

  async query(sql, params) {
    if (!this.failureMode) {
      return this.pool.query(sql, params);
    }

    switch (this.failureMode.mode) {
      case 'timeout':
        await new Promise(r => setTimeout(r, this.failureMode.options.duration || 30000));
        throw new Error('Query timeout');

      case 'error':
        throw new Error(this.failureMode.options.message || 'Database error');

      case 'corrupt':
        const result = await this.pool.query(sql, params);
        return this.corruptResult(result);

      case 'disconnect':
        await this.pool.end();
        throw new Error('Connection closed');

      case 'slow':
        await new Promise(r => setTimeout(r, this.failureMode.options.delay || 1000));
        return this.pool.query(sql, params);

      default:
        return this.pool.query(sql, params);
    }
  }

  corruptResult(result) {
    if (result.rows) {
      result.rows = result.rows.map(row => {
        const corrupted = { ...row };
        // Corrupt random fields
        Object.keys(corrupted).forEach(key => {
          if (Math.random() > 0.5) {
            if (typeof corrupted[key] === 'string') {
              corrupted[key] = corrupted[key].split('').reverse().join('');
            } else if (typeof corrupted[key] === 'number') {
              corrupted[key] = corrupted[key] * -1;
            }
          }
        });
        return corrupted;
      });
    }
    return result;
  }
}

// Usage
const db = new DatabaseFailureInjector(pool);

// In tests
describe('Database failure tests', () => {
  it('should handle timeout', async () => {
    db.enableFailure('timeout', { duration: 5000 });

    try {
      await api.getUsers();
      fail('Should have timed out');
    } catch (error) {
      expect(error.message).toContain('timeout');
    }

    db.disableFailure();
  });

  it('should handle corrupt data', async () => {
    db.enableFailure('corrupt');

    const users = await api.getUsers();
    // Users might be corrupted, but API should handle it
    expect(Array.isArray(users)).toBe(true);

    db.disableFailure();
  });
});
