SLA testing verifies that your API meets its promised service levels. This includes availability, response time, and error rate guarantees.

**SLA Test Example:**

```javascript
// reliability/sla-test.js
const axios = require('axios');

class SLATester {
  constructor(config) {
    this.endpoint = config.endpoint;
    this.expectedAvailability = config.availability || 99.9; // %
    this.expectedResponseTime = config.responseTime || 200; // ms
    this.expectedErrorRate = config.errorRate || 0.1; // %
    this.results = [];
  }

  async run(duration = 60000, interval = 1000) {
    console.log(`Running SLA test for ${duration/1000}s...`);
    const endTime = Date.now() + duration;

    while (Date.now() < endTime) {
      await this.testRequest();
      await new Promise(r => setTimeout(r, interval));
    }

    return this.analyze();
  }

  async testRequest() {
    const start = Date.now();
    try {
      const response = await axios.get(this.endpoint, { timeout: 5000 });
      this.results.push({
        timestamp: Date.now(),
        success: true,
        status: response.status,
        duration: Date.now() - start
      });
    } catch (error) {
      this.results.push({
        timestamp: Date.now(),
        success: false,
        error: error.message,
        duration: Date.now() - start
      });
    }
  }

  analyze() {
    const total = this.results.length;
    const successes = this.results.filter(r => r.success);
    const failures = this.results.filter(r => !r.success);

    const availability = (successes.length / total) * 100;
    const avgResponseTime = successes.reduce((acc, r) => acc + r.duration, 0) / successes.length;
    const p95ResponseTime = successes.map(r => r.duration).sort()[Math.floor(successes.length * 0.95)];

    return {
      total,
      successes: successes.length,
      failures: failures.length,
      availability,
      meetsAvailability: availability >= this.expectedAvailability,
      avgResponseTime,
      p95ResponseTime,
      meetsResponseTime: avgResponseTime <= this.expectedResponseTime,
      errorRate: (failures.length / total) * 100,
      meetsErrorRate: (failures.length / total) * 100 <= this.expectedErrorRate,
      slaLabels: this.results.map(r => ({
        timestamp: new Date(r.timestamp).toISOString(),
        success: r.success,
        duration: r.duration,
        status: r.status
      }))
    };
  }
}

// Usage
const tester = new SLATester({
  endpoint: 'https://api.example.com/health',
  availability: 99.5,
  responseTime: 300,
  errorRate: 0.5
});

const results = await tester.run(60000); // 1 minute
console.log('SLA Results:', {
  availability: `${results.availability.toFixed(2)}%`,
  avgResponseTime: `${results.avgResponseTime.toFixed(0)}ms`,
  errorRate: `${results.errorRate.toFixed(2)}%`,
  passed: results.meetsAvailability && results.meetsResponseTime
});
```

**Multi-Region Uptime Test:**

```javascript
// reliability/uptime-test.js
class UptimeTester {
  constructor(endpoints) {
    this.endpoints = endpoints; // { name: 'us-east', url: '...' }
    this.status = {};
  }

  async testAll() {
    const results = await Promise.all(
      this.endpoints.map(async (endpoint) => {
        const start = Date.now();
        try {
          const response = await axios.get(endpoint.url, { timeout: 5000 });
          return {
            region: endpoint.name,
            status: 'up',
            responseTime: Date.now() - start,
            timestamp: Date.now()
          };
        } catch (error) {
          return {
            region: endpoint.name,
            status: 'down',
            error: error.message,
            timestamp: Date.now()
          };
        }
      })
    );

    results.forEach(r => {
      this.status[r.region] = r;
    });

    return results;
  }

  getUptimePercentage() {
    // Track over time with database
    return '98.5%';
  }
}

// Usage
const uptime = new UptimeTester([
  { name: 'us-east', url: 'https://us-east.api.example.com/health' },
  { name: 'eu-west', url: 'https://eu-west.api.example.com/health' },
  { name: 'ap-south', url: 'https://ap-south.api.example.com/health' }
]);

setInterval(async () => {
  const results = await uptime.testAll();
  const down = results.filter(r => r.status === 'down');
  if (down.length > 0) {
    console.log('⚠️ Regions down:', down.map(d => d.region));
  }
}, 60000); // Test every minute
```

**Key Insight:** SLA testing should be continuous. Run these tests from multiple locations and alert on violations.

Proper timeout and retry handling prevents cascading failures and improves user experience.

**Timeout Test Examples:**

```javascript
// reliability/timeout-test.js
describe('Timeout Tests', () => {
  it('should timeout after configured duration', async () => {
    const start = Date.now();
    try {
      await axios.get('https://api.example.com/slow-endpoint', {
        timeout: 1000 // 1 second
      });
      throw new Error('Should have timed out');
    } catch (error) {
      expect(error.code).toBe('ECONNABORTED');
      const duration = Date.now() - start;
      expect(duration).toBeGreaterThanOrEqual(900);
      expect(duration).toBeLessThan(2000);
    }
  });

  it('should have different timeouts per endpoint', async () => {
    // Fast endpoint works with short timeout
    const fast = await axios.get('https://api.example.com/fast', {
      timeout: 100
    });
    expect(fast.status).toBe(200);

    // Slow endpoint needs longer timeout
    try {
      await axios.get('https://api.example.com/slow', {
        timeout: 100
      });
      throw new Error('Should have timed out');
    } catch (error) {
      expect(error.code).toBe('ECONNABORTED');
    }
  });
});
```

**Retry Logic Test:**

```javascript
// reliability/retry-test.js
class RetryTester {
  constructor(maxRetries = 3) {
    this.maxRetries = maxRetries;
    this.attempts = [];
  }

  async testWithRetries(failuresBeforeSuccess) {
    this.attempts = [];

    try {
      const result = await this.makeRequestWithRetry(failuresBeforeSuccess);
      return { success: true, attempts: this.attempts, result };
    } catch (error) {
      return { success: false, attempts: this.attempts, error: error.message };
    }
  }

  async makeRequestWithRetry(failuresBeforeSuccess) {
    let lastError;

    for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
      this.attempts.push({ attempt, time: Date.now() });

      try {
        if (attempt < failuresBeforeSuccess) {
          throw new Error('Simulated failure');
        }
        return { status: 200, data: 'success' };
      } catch (error) {
        lastError = error;
        if (attempt === this.maxRetries) break;

        // Exponential backoff
        const delay = Math.pow(2, attempt) * 100;
        await new Promise(r => setTimeout(r, delay));
      }
    }

    throw lastError;
  }

  analyze() {
    const results = [];
    for (let fails = 0; fails <= 5; fails++) {
      const result = this.testWithRetries(fails);
      results.push({ failures: fails, ...result });
    }
    return results;
  }
}

// Test
describe('Retry Logic', () => {
  it('should succeed after 2 failures', async () => {
    const tester = new RetryTester(3);
    const result = await tester.testWithRetries(2);

    expect(result.success).toBe(true);
    expect(result.attempts.length).toBe(3); // Initial + 2 retries
  });

  it('should fail after max retries', async () => {
    const tester = new RetryTester(3);
    const result = await tester.testWithRetries(5);

    expect(result.success).toBe(false);
    expect(result.attempts.length).toBe(4); // Initial + 3 retries
  });

  it('should use exponential backoff', async () => {
    const tester = new RetryTester(3);
    await tester.testWithRetries(3);

    const delays = [];
    for (let i = 1; i < tester.attempts.length; i++) {
      delays.push(tester.attempts[i].time - tester.attempts[i-1].time);
    }

    // Check increasing delays
    expect(delays[1]).toBeGreaterThan(delays[0]);
    expect(delays[2]).toBeGreaterThan(delays[1]);
  });
});
```

**Key Insight:** Test both success and failure paths. Verify that retries happen with proper backoff and that timeouts are appropriate per endpoint.

Circuit breakers prevent cascading failures by stopping requests to failing services.

**Circuit Breaker Test:**

```javascript
// reliability/circuit-breaker-test.js
class CircuitBreaker {
  constructor(options = {}) {
    this.failureThreshold = options.failureThreshold || 3;
    this.resetTimeout = options.resetTimeout || 30000;
    this.failures = 0;
    this.state = 'CLOSED';
    this.nextAttempt = Date.now();
  }

  async call(fn) {
    if (this.state === 'OPEN') {
      if (Date.now() > this.nextAttempt) {
        this.state = 'HALF_OPEN';
      } else {
        throw new Error('Circuit breaker is OPEN');
      }
    }

    try {
      const result = await fn();
      this.onSuccess();
      return result;
    } catch (error) {
      this.onFailure();
      throw error;
    }
  }

  onSuccess() {
    this.failures = 0;
    this.state = 'CLOSED';
  }

  onFailure() {
    this.failures++;
    if (this.failures >= this.failureThreshold) {
      this.state = 'OPEN';
      this.nextAttempt = Date.now() + this.resetTimeout;
    }
  }
}

// Tests
describe('Circuit Breaker', () => {
  let breaker;

  beforeEach(() => {
    breaker = new CircuitBreaker({ failureThreshold: 2, resetTimeout: 1000 });
  });

  it('should open after threshold failures', async () => {
    const failingFn = async () => { throw new Error('fail'); };

    try { await breaker.call(failingFn); } catch (e) {}
    try { await breaker.call(failingFn); } catch (e) {}

    // Third call should throw circuit open error
    try {
      await breaker.call(failingFn);
      throw new Error('Should not reach');
    } catch (error) {
      expect(error.message).toBe('Circuit breaker is OPEN');
    }
  });

  it('should reset after timeout', async () => {
    const failingFn = async () => { throw new Error('fail'); };

    // Open circuit
    try { await breaker.call(failingFn); } catch (e) {}
    try { await breaker.call(failingFn); } catch (e) {}

    // Wait for reset
    await new Promise(r => setTimeout(r, 1100));

    // Should try again (half-open)
    try {
      await breaker.call(failingFn);
    } catch (error) {
      expect(error.message).toBe('fail'); // Original error, not circuit open
    }
  });

  it('should close after success in half-open', async () => {
    let shouldFail = true;
    const flakyFn = async () => {
      if (shouldFail) throw new Error('fail');
      return 'success';
    };

    // Open circuit
    try { await breaker.call(flakyFn); } catch (e) {}
    try { await breaker.call(flakyFn); } catch (e) {}

    // Wait for half-open
    await new Promise(r => setTimeout(r, 1100));

    // Succeed in half-open
    shouldFail = false;
    const result = await breaker.call(flakyFn);
    expect(result).toBe('success');
    expect(breaker.state).toBe('CLOSED');
  });
});
```

**API Circuit Breaker Integration Test:**

```javascript
// reliability/api-circuit-test.js
describe('API Circuit Breaker', () => {
  it('should return 503 when circuit is open', async () => {
    // Trigger failures
    for (let i = 0; i < 5; i++) {
      try {
        await axios.post('https://api.example.com/payments', {
          amount: -100 // Invalid amount
        });
      } catch (e) {}
    }

    // Next request should get 503
    try {
      await axios.post('https://api.example.com/payments', {
        amount: 100
      });
    } catch (error) {
      expect(error.response.status).toBe(503);
      expect(error.response.headers['x-circuit-open']).toBe('true');
    }
  });

  it('should include retry-after header', async () => {
    try {
      await axios.get('https://api.example.com/failing-service');
    } catch (error) {
      if (error.response.status === 503) {
        expect(error.response.headers['retry-after']).toBeDefined();
      }
    }
  });
});
```

**Key Insight:** Circuit breakers should be tested for all three states: closed (normal), open (failing fast), and half-open (testing recovery).

Failover testing verifies that your system can automatically switch to backup components when primary components fail.

**Failover Test Examples:**

```javascript
// reliability/failover-test.js
class FailoverTester {
  constructor(primaryUrl, backupUrl) {
    this.primary = primaryUrl;
    this.backup = backupUrl;
    this.active = primaryUrl;
    this.failoverCount = 0;
  }

  async testFailover() {
    console.log('Testing failover mechanism...');

    // 1. Test primary
    const primaryOk = await this.checkHealth(this.primary);
    console.log(`Primary: ${primaryOk ? 'OK' : 'DOWN'}`);

    // 2. Simulate primary failure
    await this.simulatePrimaryFailure();

    // 3. Verify failover to backup
    const backupOk = await this.checkHealth(this.backup);
    console.log(`Backup after failover: ${backupOk ? 'OK' : 'DOWN'}`);

    // 4. Test API through load balancer
    const apiOk = await this.checkHealth('https://api.example.com');
    console.log(`API endpoint: ${apiOk ? 'OK' : 'DOWN'}`);

    // 5. Test recovery
    await this.recoverPrimary();
    const recovered = await this.checkHealth(this.primary);
    console.log(`Primary recovered: ${recovered ? 'OK' : 'DOWN'}`);

    return {
      primaryOk,
      backupOk,
      apiOk,
      recovered,
      failoverCount: this.failoverCount
    };
  }

  async checkHealth(url) {
    try {
      const response = await axios.get(`${url}/health`, { timeout: 2000 });
      return response.status === 200;
    } catch {
      return false;
    }
  }

  async simulatePrimaryFailure() {
    // In real test, this might involve:
    // - Stopping the primary service
    // - Blocking network access
    // - Causing process crash
    console.log('Simulating primary failure...');
    this.failoverCount++;
    this.active = this.backup;
  }

  async recoverPrimary() {
    console.log('Recovering primary...');
    this.active = this.primary;
  }
}

// Test
describe('Failover Tests', () => {
  it('should failover within acceptable time', async () => {
    const tester = new FailoverTester(
