**SLO Monitoring Test:**

```javascript
// reliability/slo-monitoring.js
class SLOValidator {
  constructor(slos) {
    this.slos = slos; // [{ name, target, window }]
    this.metrics = [];
  }

  async run(windowMs = 60000) {
    const start = Date.now();
    const end = start + windowMs;

    while (Date.now() < end) {
      await this.collectMetrics();
      await new Promise(r => setTimeout(r, 1000));
    }

    return this.validateSLOs();
  }

  async collectMetrics() {
    const response = await axios.get('https://api.example.com/metrics');
    this.metrics.push({
      timestamp: Date.now(),
      availability: response.data.availability,
      latency: response.data.latency_p95,
      errorRate: response.data.error_rate
    });
  }

  validateSLOs() {
    const results = [];

    for (const slo of this.slos) {
      let passed = true;

      if (slo.name === 'availability') {
        const avg = this.metrics.reduce((acc, m) => acc + m.availability, 0) / this.metrics.length;
        passed = avg >= slo.target;
        results.push({ slo: slo.name, target: slo.target, actual: avg, passed });
      }

      if (slo.name === 'latency') {
        const p95 = this.metrics.map(m => m.latency).sort()[Math.floor(this.metrics.length * 0.95)];
        passed = p95 <= slo.target;
        results.push({ slo: slo.name, target: slo.target, actual: p95, passed });
      }
    }

    return results;
  }
}

// Usage
const validator = new SLOValidator([
  { name: 'availability', target: 99.9, window: '1h' },
  { name: 'latency', target: 200, window: '1h' }
]);

const results = await validator.run(60000);
console.log('SLO Validation:', results);
```

**Key Insight:** Test your monitoring as thoroughly as you test your API. False negatives (missed alerts) and false positives (noise) both cause problems.

