**Key Insight:** Test each CRUD operation individually, then test sequences. The order matters—a delete after update should behave differently than update after delete.

APIs often need to perform multiple operations as a single transaction. Test that these transactions maintain ACID properties.

**Atomicity Tests:**

```javascript
// integrity/atomicity-test.js
describe('Transaction Atomicity', () => {
  it('should commit when all operations succeed', async () => {
    const orderData = {
      userId: 123,
      items: [
        { productId: 456, quantity: 2 },
        { productId: 789, quantity: 1 }
      ],
      payment: {
        method: 'card',
        amount: 59.97
      }
    };

    const response = await axios.post('https://api.example.com/orders', orderData);
    expect(response.status).toBe(201);

    const orderId = response.data.id;

    // Verify order exists
    const order = await axios.get(`https://api.example.com/orders/${orderId}`);
    expect(order.status).toBe(200);

    // Verify inventory updated
    const product1 = await axios.get('https://api.example.com/products/456');
    expect(product1.data.stock).toBe(originalStock1 - 2);

    // Verify payment processed
    const payment = await axios.get(`https://api.example.com/payments/${order.data.paymentId}`);
    expect(payment.status).toBe(200);
  });

  it('should rollback when any operation fails', async () => {
    const originalStock = await getProductStock(456);

    const orderData = {
      userId: 123,
      items: [
        { productId: 456, quantity: 2 },
        { productId: 999, quantity: 1 } // Non-existent product
      ],
      payment: {
        method: 'card',
        amount: 59.97
      }
    };

    try {
      await axios.post('https://api.example.com/orders', orderData);
    } catch (error) {
      expect(error.response.status).toBe(400);

      // Verify inventory was rolled back
      const product = await axios.get('https://api.example.com/products/456');
      expect(product.data.stock).toBe(originalStock);

      // Verify no payment was processed
