Distributed systems often use eventual consistency. Test that data converges correctly over time.

**Eventual Consistency Tests:**

```javascript
// integrity/eventual-consistency.js
class EventualConsistencyTester {
  constructor(endpoints) {
    this.endpoints = endpoints; // Different replicas
  }

  async testWriteReadConsistency(key, value) {
    // Write to primary
    const writeResponse = await axios.post('https://api.example.com/data', {
      key, value
    });
    const writeTime = Date.now();

    // Read from all replicas at different times
    const results = [];

    for (let delay = 0; delay <= 5000; delay += 1000) {
      await new Promise(r => setTimeout(r, delay));

      const replicaResults = await Promise.all(
        this.endpoints.map(async (endpoint) => {
          try {
            const response = await axios.get(`${endpoint}/data/${key}`);
            return {
              replica: endpoint,
              value: response.data.value,
              consistent: response.data.value === value
            };
          } catch (error) {
            return {
              replica: endpoint,
              error: error.message,
              consistent: false
            };
          }
        })
      );

      results.push({
        timeMs: delay,
        replicas: replicaResults
      });
    }

    return {
      key,
      writeTime,
      convergenceTime: this.findConvergenceTime(results),
      results
    };
  }

  findConvergenceTime(results) {
    for (const result of results) {
      if (result.replicas.every(r => r.consistent)) {
        return result.timeMs;
      }
    }
    return null;
  }

  async testConflictResolution(key, value1, value2) {
    // Write conflicting values to different replicas simultaneously
    const write1 = axios.post('https://replica-1.api.example.com/data', {
      key, value: value1
    });

    const write2 = axios.post('https://replica-2.api.example.com/data', {
      key, value: value2
    });

    await Promise.all([write1, write2]);

    // Wait for convergence
    await new Promise(r => setTimeout(r, 5000));

    // Read from all replicas
    const reads = await Promise.all(
      this.endpoints.map(e => 
        axios.get(`${e}/data/${key}`).catch(() => null)
      )
    );

    const values = reads.filter(r => r).map(r => r.data.value);
    const uniqueValues = [...new Set(values)];

    return {
      key,
      conflicts: uniqueValues.length > 1,
      resolvedValue: uniqueValues[0],
      resolutionStrategy: this.detectResolutionStrategy(values)
    };
  }

  detectResolutionStrategy(values) {
    const first = values[0];
    if (values.every(v => v === first)) {
      if (first === 'value1') return 'first-write-wins';
      if (first === 'value2') return 'last-write-wins';
      return 'consistent';
    }
    return 'divergent';
  }
}

// Usage in test
describe('Eventual Consistency', () => {
  const tester = new EventualConsistencyTester([
    'https://replica-1.api.example.com',
    'https://replica-2.api.example.com',
    'https://replica-3.api.example.com'
  ]);

  it('should converge within 5 seconds', async () => {
    const result = await tester.testWriteReadConsistency(
      'test-key', 
      'test-value-' + Date.now()
    );

    expect(result.convergenceTime).toBeLessThanOrEqual(5000);
  });

  it('should resolve conflicts with last-write-wins', async () => {
    const result = await tester.testConflictResolution(
      'conflict-key',
      'first-value',
      'second-value'
    );

    // Should converge to one value
    expect(result.conflicts).toBe(false);
    expect(result.resolvedValue).toBeDefined();
  });
});
